(window.APUSH_TOPICS=window.APUSH_TOPICS||{})[7]=[{"id": "p7-001", "period": 7, "topic_en": "Alfred Thayer Mahan and navalism", "topic_zh": "马汉海权论与海军扩张", "year": 1890, "year_text": "The Influence of Sea Power upon History, 1890", "who": ["Alfred Thayer Mahan"], "who_zh": ["阿尔弗雷德·赛耶·马汉"], "what_en": "In The Influence of Sea Power upon History (1890), U.S. naval officer Alfred Thayer Mahan urged the United States to build a powerful navy, observing that naval power had been essential to past empires. As early as 1886 Congress ordered two steel-hulled battleships, the USS Texas and USS Maine, and in 1890 appropriated funds for three more.", "what_zh": "1890年，美国海军军官马汉在《海权对历史的影响》中敦促美国建设强大海军，指出海权是过去帝国成功的关键。国会早在1886年就订购了两艘钢壳战列舰（USS Texas、USS Maine），1890年又拨款建造三艘。", "cause_en": "Fear of ruthless international competition as European powers amassed steel-plated battleships and carved up Africa and Asia; the belief, fed by racialized Social Darwinism, that great powers needed navies to compete.", "cause_zh": "欧洲列强竞相建造钢甲战列舰、瓜分亚非，引发对残酷国际竞争的恐惧；社会达尔文主义也助长了大国需靠海军竞争的观念。", "sig_en": "Mahan's book supplied the intellectual foundation for the U.S. naval buildup and the turn to overseas expansion in the 1890s.", "sig_zh": "马汉的著作为美国海军扩张和1890年代转向海外扩张提供了理论基础。", "why_term": "sea power", "why_term_q": "Mahan argued that ______ had been essential to past empires.", "exp_en": "Mahan's 1890 argument that sea power made empires gave policymakers the doctrine behind the battleship program that enabled American imperialism.", "exp_zh": "马汉1890年提出海权造就帝国的论点，为战列舰计划和美国帝国主义提供了理论依据。", "page": 674}, {"id": "p7-002", "period": 7, "topic_en": "War of 1898", "topic_zh": "1898年美西战争", "year": 1898, "year_text": "1898", "who": ["William Randolph Hearst", "William McKinley", "Theodore Roosevelt", "George Dewey"], "who_zh": ["威廉·伦道夫·赫斯特", "威廉·麦金莱", "西奥多·罗斯福", "乔治·杜威"], "what_en": "After the Cuban guerrilla war against Spain (1895) and the explosion of the USS Maine in Havana harbor in February 1898 (260 seamen lost), Remember the Maine became a national chant. Congress declared war in April 1898; Dewey destroyed the Spanish fleet at Manila Bay on May 1, U.S. troops took San Juan Hill on July 1, and Spain soon surrendered. In the Treaty of Paris, Spain freed Cuba and ceded Puerto Rico and Guam to the United States and sold the Philippines for $20 million.", "what_zh": "1895年古巴爆发反西班牙游击战；1898年2月缅因号在哈瓦那港爆炸（260名水兵丧生），记住缅因号成为全国口号。国会4月宣战，杜威5月1日在马尼拉湾歼灭西班牙舰队，美军7月1日攻占圣胡安山，西班牙很快投降。《巴黎条约》规定西班牙解放古巴，割让波多黎各、关岛，并以2000万美元将菲律宾卖给美国。", "cause_en": "Spanish concentration camps in Cuba (as many as 200,000 civilians died), yellow journalism by Hearst, the de Lome letter, the Maine explosion, and U.S. strategic interests including a proposed canal and sugar plantations.", "cause_zh": "西班牙在古巴设立集中营（多达20万平民死亡）、赫斯特的黄色新闻、德洛姆信件、缅因号爆炸，以及美国在运河和蔗糖种植园方面的战略利益。", "sig_en": "Victory made the United States an imperial power with Caribbean and Pacific possessions, and led directly to the bloody U.S.-Philippine War.", "sig_zh": "胜利使美国成为拥有加勒比和太平洋属地的帝国强国，并直接引发了血腥的美菲战争。", "exp_en": "The War of 1898 turned a Cuban rebellion and the Maine disaster into America's first step as an overseas empire, ending with the Treaty of Paris cessions.", "exp_zh": "1898年战争把古巴起义和缅因号灾难变成美国迈向海外帝国的第一步，以《巴黎条约》的割地告终。", "page": 675}, {"id": "p7-003", "period": 7, "topic_en": "Teller Amendment", "topic_zh": "泰勒修正案", "year": 1898, "year_text": "1898", "who": ["Henry M. Teller"], "who_zh": ["亨利·M·特勒"], "what_en": "Senator Henry M. Teller of Colorado added an amendment to the 1898 war bill disclaiming any intention by the United States to occupy Cuba. It reassured Americans that their country would uphold democracy abroad as well as at home.", "what_zh": "1898年，科罗拉多州参议员亨利·M·特勒在战争法案中加入修正案，声明美国无意占领古巴，让美国人相信本国在海外也会维护民主。", "cause_en": "The McKinley administration had defeated a congressional attempt to recognize the Cuban rebel government, raising fears the United States might simply seize Cuba.", "cause_zh": "麦金莱政府挫败了国会承认古巴起义政府的企图，引发美国可能直接吞并古巴的担忧。", "sig_en": "It legally bound the United States not to annex Cuba, though the later Platt Amendment (1902) still sharply limited Cuban independence.", "sig_zh": "它在法律上约束美国不得吞并古巴，但后来的普拉特修正案（1902）仍严重限制了古巴独立。", "exp_en": "The Teller Amendment was Congress's promise that the War of 1898 was about Cuban freedom, not American conquest.", "exp_zh": "泰勒修正案是国会作出的承诺：1898年战争是为了古巴自由，而非美国征服。", "page": 675}, {"id": "p7-004", "period": 7, "topic_en": "U.S.-Philippine War", "topic_zh": "美菲战争", "year": 1899, "year_text": "1899-1902", "who": ["Emilio Aguinaldo", "William McKinley", "William Howard Taft"], "who_zh": ["埃米利奥·阿奎那多", "威廉·麦金莱", "威廉·霍华德·塔夫脱"], "what_en": "After the Treaty of Paris ceded the Philippines to the United States for $20 million, fighting broke out on February 4, 1899 between American and Filipino patrols. Rebel leader Emilio Aguinaldo asserted Philippine independence and fought U.S. occupation. In three years, 4,200 Americans and an estimated 200,000 Filipinos died; the fighting ended in 1902, and William Howard Taft became governor-general.", "what_zh": "《巴黎条约》以2000万美元把菲律宾割让给美国后，1899年2月4日美菲巡逻队爆发冲突。起义领袖阿奎那多宣布菲律宾独立并抗击美军。三年战争中4200名美军和约20万菲律宾人死亡；1902年战争结束，塔夫脱出任总督。", "cause_en": "McKinley's decision to annex the Philippines, declaring Filipinos unfit for self-rule, collided with Filipino nationalists' determination to be independent.", "cause_zh": "麦金莱决定吞并菲律宾，宣称菲律宾人不适合自治，与菲律宾民族主义者的独立决心发生冲突。", "sig_en": "The brutal war stained imperialism's moral claims at home and the Jones Act of 1916 later committed the United States to eventual Philippine independence.", "sig_zh": "这场残酷战争玷污了帝国主义在国内的道德主张；1916年《琼斯法案》后来承诺菲律宾最终独立。", "src": {"text": "we could not leave [the Filipinos] to themselves - they were unfit for self-rule.", "attr": "William McKinley"}, "exp_en": "The U.S.-Philippine War showed that taking an empire meant fighting the people who lived there; Aguinaldo's resistance cost 200,000 Filipino lives.", "exp_zh": "美菲战争表明夺取帝国意味着与当地人民作战；阿奎那多的抵抗付出了20万菲律宾人生命的代价。", "page": 678}, {"id": "p7-005", "period": 7, "topic_en": "Platt Amendment", "topic_zh": "普拉特修正案", "year": 1902, "year_text": "1902", "who": [], "who_zh": [], "what_en": "As a condition for withdrawing from Cuba, the United States forced the newly independent island to accept a proviso in its constitution called the Platt Amendment (1902). It blocked Cuba from making a treaty with any country except the United States, gave the United States the right to intervene in Cuban affairs, and granted a U.S. lease on Guantanamo Bay, where the Navy built a large base.", "what_zh": "作为从古巴撤军的条件，美国迫使新独立的古巴在宪法中接受普拉特修正案（1902）：古巴不得与美国以外的国家缔约，美国有权干涉古巴事务，古巴还把关塔那摩湾租给美国海军建大型基地。", "cause_en": "U.S. policymakers wanted to limit the independence the Teller Amendment had promised and secure a Caribbean naval base.", "cause_zh": "美国决策者想限制泰勒修正案承诺过的独立，并确保获得加勒比海军基地。", "sig_en": "Cubans' hard-won independence was sharply limited, creating a quasi-colonial relationship that lasted for decades.", "sig_zh": "古巴人来之不易的独立受到严重限制，形成了持续数十年的准殖民关系。", "exp_en": "The Platt Amendment shows how the Teller Amendment's promise of Cuban freedom was hollowed out into a U.S. right of intervention.", "exp_zh": "普拉特修正案表明，泰勒修正案关于古巴自由的承诺如何被掏空，变成美国的干涉权。", "page": 678}, {"id": "p7-006", "period": 7, "topic_en": "Insular Cases", "topic_zh": "岛屿案", "year": 1901, "year_text": "1901", "who": [], "who_zh": [], "what_en": "In 1901 the Supreme Court upheld, in a set of decisions known as the Insular Cases, that the Constitution did not automatically extend citizenship to people in acquired territories and that Congress could decide their status. Puerto Rico, Guam, and the Philippines were thus marked as colonies, not future states.", "what_zh": "1901年，最高法院在一系列被称为岛屿案的判决中裁定，宪法并不自动赋予新获领土居民公民身份，国会有权决定其地位。波多黎各、关岛和菲律宾因此被定为殖民地，而非未来的州。", "cause_en": "Constitutional uncertainty after the United States annexed overseas territories; the Treaty of Paris had guaranteed religious freedom but withheld any promise of citizenship.", "cause_zh": "美国吞并海外领土后出现宪法上的不确定性；《巴黎条约》保障了宗教自由，但未承诺公民身份。", "sig_en": "The decisions gave constitutional cover to American colonial rule over the new possessions.", "sig_zh": "这些判决为美国对新属地的殖民统治提供了宪法依据。", "exp_en": "The Insular Cases answered the empire's legal question: the Constitution did not follow the flag, so Congress could rule colonies indefinitely.", "exp_zh": "岛屿案回答了帝国的法律问题：宪法不随国旗而行，国会可以无限期统治殖民地。", "page": 678}, {"id": "p7-007", "period": 7, "topic_en": "Open Door policy", "topic_zh": "门户开放政策", "year": 1899, "year_text": "1899 (second note 1900)", "who": ["John Hay"], "who_zh": ["约翰·海"], "what_en": "In 1899 Secretary of State John Hay sent the European powers and Japan a note claiming the right of equal trade access, an open door, for all nations doing business in China. When the Boxer Rebellion broke out in 1900, Hay asserted a second open door principle: China must be preserved as a territorial and administrative entity.", "what_zh": "1899年，国务卿约翰·海向欧洲列强和日本发出照会，主张各国在中国享有平等的贸易机会，即门户开放。1900年义和团运动爆发后，海又提出第二条原则：中国必须作为领土和行政实体被保存下来。", "cause_en": "Fear of being shut out as Japan, Russia, Germany, France, and Britain divided coastal China into spheres of influence after the Sino-Japanese War of 1894-1895.", "cause_zh": "甲午战争后日、俄、德、法、英把中国沿海划为势力范围，美国担心被排挤在外。", "sig_en": "The United States inserted itself into Chinese affairs without colonies, entangling itself in China and beginning a long-term Pacific rivalry with Japan.", "sig_zh": "美国在没有殖民地的情况下介入中国事务，从此卷入中国，并开启了与日本的长期太平洋竞争。", "exp_en": "The Open Door let the United States claim China's markets by diplomacy instead of colonies, but it tied American fortunes to China and Japan's rivalry.", "exp_zh": "门户开放让美国以外交而非殖民的方式宣示对中国市场的权利，但也把美国命运与中日竞争绑在一起。", "page": 679, "img": {"file": "img:f2_882", "credit": "图源：Henretta《America's History》第8版 p.679"}}, {"id": "p7-008", "period": 7, "topic_en": "Panama Canal", "topic_zh": "巴拿马运河", "year": 1914, "year_text": "opened 1914 (Panama recognized 1903)", "who": ["Theodore Roosevelt"], "who_zh": ["西奥多·罗斯福"], "what_en": "Roosevelt secured canal-building rights when Britain surrendered them in the Hay-Pauncefote Treaty (1901). When Colombia rejected the U.S. offer for a canal zone, the United States backed a Panamanian independence movement; on November 6, 1903 it recognized Panama, and two weeks later obtained a perpetually renewable canal-zone lease. The Army Corps of Engineers hired 60,000 laborers, excavated 240 million cubic yards of earth, and built immense locks; the canal opened in 1914.", "what_zh": "英国在1901年《海-庞斯福特条约》中放弃运河权后，罗斯福获得修建权。哥伦比亚拒绝美国方案后，美国支持巴拿马独立运动；1903年11月6日美国承认巴拿马，两周后获得永久续租的运河区。陆军工程兵团雇佣6万劳工，挖掘2.4亿立方码土方，建造巨大船闸；运河1914年通航。", "cause_en": "Roosevelt's belief that naval power required rapid access to two oceans (speak softly and carry a big stick); European powers conceded the U.S. paramount interest in the Caribbean.", "cause_zh": "罗斯福认为海军需要两洋间的快速通道（温言在口，大棒在手）；欧洲列强承认美国在加勒比的首要利益。", "sig_en": "The canal gave the United States a commanding position in the Western Hemisphere, at the cost of thousands of workers' lives; the United States paid Colombia $25 million in 1922 as conscience money.", "sig_zh": "运河使美国在西半球占据主导地位，代价是数千劳工的生命；1922年美国向哥伦比亚支付2500万美元作为良心补偿。", "exp_en": "The Panama Canal was the engineering triumph that made Roosevelt's big-stick diplomacy concrete: two oceans joined under American control.", "exp_zh": "巴拿马运河是罗斯福大棒外交的工程丰碑：两大洋在美国控制下连为一体。", "page": 682, "img": {"file": "img:f2_889", "credit": "图源：Henretta《America's History》第8版 p.682"}}, {"id": "p7-009", "period": 7, "topic_en": "Roosevelt Corollary", "topic_zh": "罗斯福推论", "year": 1904, "year_text": "1904", "who": ["Theodore Roosevelt"], "who_zh": ["西奥多·罗斯福"], "what_en": "In 1904 Roosevelt announced that the United States would police all of the Caribbean. The Roosevelt Corollary to the Monroe Doctrine asserted the United States's unrestricted right to regulate Caribbean affairs, and the United States intervened regularly in Caribbean and Central American nations over the next three decades.", "what_zh": "1904年罗斯福宣布美国将对整个加勒比行使警察权。门罗主义的罗斯福推论主张美国有权无限制地管制加勒比事务，此后三十年美国不断干涉加勒比和中美洲国家。", "cause_en": "Roosevelt argued that regional instability invited European intervention, which the United States had to preempt.", "cause_zh": "罗斯福认为地区不稳定会招致欧洲干涉，美国必须先发制人。", "sig_en": "It turned the Monroe Doctrine upside down: instead of protecting neighbors' independence from Europe, it claimed a U.S. right to intervene, justifying decades of interventions.", "sig_zh": "它把门罗主义颠倒过来：不再是保护邻国免受欧洲侵犯，而是宣示美国的干涉权，为数十年的干涉辩护。", "why_term": "Roosevelt Corollary", "why_term_q": "The 1904 declaration that the United States would police the Caribbean is the ______.", "exp_en": "The Roosevelt Corollary converted the Monroe Doctrine from a shield for Latin America into a license for U.S. intervention.", "exp_zh": "罗斯福推论把门罗主义从拉丁美洲的盾牌变成了美国干涉的许可证。", "page": 683, "img": {"file": "img:f2_892", "credit": "图源：Henretta《America's History》第8版 p.683"}}, {"id": "p7-010", "period": 7, "topic_en": "Zimmermann telegram and U.S. entry into World War I", "topic_zh": "齐默尔曼电报与美国参加一战", "year": 1917, "year_text": "1917 (war declared April 6, 1917)", "who": ["Arthur Zimmermann", "Woodrow Wilson", "Jeannette Rankin"], "who_zh": ["阿图尔·齐默尔曼", "伍德罗·威尔逊", "珍妮特·兰金"], "what_en": "Germany resumed unrestricted submarine warfare in February 1917. Newspapers then published the Zimmermann telegram, in which German foreign secretary Arthur Zimmermann urged Mexico to join the Central Powers, promising help to recover the lost territory of Texas, New Mexico, and Arizona. After U-boats sank three U.S. ships on March 18, Wilson asked Congress for war on April 2, promising to make the world safe for democracy; the United States declared war on Germany on April 6, with six senators and fifty House members opposed, including Jeannette Rankin.", "what_zh": "1917年2月德国恢复无限制潜艇战。报纸随后公布齐默尔曼电报：德国外长齐默尔曼敦促墨西哥加入同盟国，承诺帮其收复得克萨斯、新墨西哥和亚利桑那。3月18日德军潜艇击沉三艘美国船后，威尔逊4月2日要求国会宣战，承诺让世界民主得到安全保障；4月6日美国对德宣战，6名参议员和50名众议员反对，包括珍妮特·兰金。", "cause_en": "German U-boat attacks on American lives and shipping (including the Lusitania in 1915, killing 128 Americans), and deep economic ties to the Allies ($3.2 billion in trade and $2.5 billion in loans versus $56 million to Germany) that undercut neutrality.", "cause_zh": "德国潜艇对美国生命和船只的攻击（包括1915年卢西塔尼亚号，128名美国人丧生），以及与协约国深厚的经济联系（32亿美元贸易、25亿美元贷款，对德国仅5600万），使中立难以为继。", "sig_en": "American troops and supplies broke the Western Front stalemate in 1918, deciding the war; Germany signed the armistice on November 11, 1918.", "sig_zh": "美军和物资1918年打破西线僵局，决定了战争胜负；德国1918年11月11日签署停战协定。", "src": {"text": "Germany would help Mexico recover the lost territory of Texas, New Mexico, and Arizona.", "attr": "Zimmermann telegram"}, "exp_en": "The Zimmermann telegram plus unrestricted submarine warfare turned American opinion: neutrality became impossible and the United States entered the war in April 1917.", "exp_zh": "齐默尔曼电报加上无限制潜艇战扭转了美国舆论：中立不再可能，美国1917年4月参战。", "page": 686}, {"id": "p7-011", "period": 7, "topic_en": "Committee on Public Information", "topic_zh": "公共信息委员会", "year": 1917, "year_text": "1917", "who": ["George Creel", "Woodrow Wilson"], "who_zh": ["乔治·克里尔", "伍德罗·威尔逊"], "what_en": "In April 1917 Wilson formed the Committee on Public Information (CPI), a government propaganda agency headed by journalist George Creel. It set out to mold Americans into one white-hot mass of war patriotism, distributing 75 million pieces of literature and enlisting thousands of Four-Minute Men to deliver short prowar speeches at movie theaters, while pressuring immigrant groups to become One Hundred Percent Americans.", "what_zh": "1917年4月，威尔逊成立公共信息委员会（CPI），由记者乔治·克里尔领导的政府宣传机构。它要把美国人塑造成一团炽热的战争爱国主义，散发7500万份宣传品，招募数千四分钟演说员在电影院发表简短挺战演说，并施压移民群体成为百分之百的美国人。", "cause_en": "The need to mobilize a diverse and divided public behind the war and to enforce 100 percent loyalty.", "cause_zh": "需要动员多元而分裂的公众支持战争，并推行百分之百的忠诚。", "sig_en": "The CPI fueled wartime conformity and nativist hysteria, especially against German Americans, that lingered into the 1920s.", "sig_zh": "CPI助长了战时的一致化要求和排外歇斯底里（尤其针对德裔美国人），其影响延续到1920年代。", "exp_en": "The Creel Committee was America's first great government propaganda machine, manufacturing consent for World War I at home.", "exp_zh": "克里尔委员会是美国第一个大型政府宣传机器，在国内为一战制造共识。", "page": 690, "img": {"file": "img:f2_916", "credit": "图源：Henretta《America's History》第8版 p.690"}}, {"id": "p7-012", "period": 7, "topic_en": "Espionage and Sedition Acts", "topic_zh": "反间谍法与反煽动法", "year": 1917, "year_text": "Espionage Act 1917; Sedition Act 1918", "who": ["Eugene V. Debs", "Oliver Wendell Holmes Jr."], "who_zh": ["尤金·V·德布斯", "小奥利弗·温德尔·霍姆斯"], "what_en": "The Espionage Act (1917) and Sedition Act (1918) prohibited words or behavior that might incite, provoke, or encourage resistance to the United States. Because treason was defined loosely, they led to more than a thousand convictions, including IWW members and Socialist leader Eugene V. Debs, sentenced to ten years. In Schenck v. United States (1919) and Abrams v. United States (1919) the Supreme Court upheld convictions, though Justices Holmes and Brandeis dissented in Abrams.", "what_zh": "1917年《反间谍法》和1918年《反煽动法》禁止任何可能煽动、挑起或鼓励反抗美国的言行。由于叛国罪定义宽泛，1000多人被定罪，包括世界产业工人联盟成员和社会党领袖德布斯（判刑十年）。1919年申克诉合众国案和艾布拉姆斯诉合众国案中最高法院维持定罪，霍姆斯和布兰代斯在后者提出异议。", "cause_en": "Wilson's near-obsession with suppressing wartime dissent and enforcing 100 percent loyalty during mobilization.", "cause_zh": "威尔逊近乎偏执地要在战争动员中压制异议、推行百分之百的忠诚。", "sig_en": "The acts chilled the political climate and, through Holmes's probing questions about clear and present danger, launched twentieth-century legal battles over free speech and civil liberties.", "sig_zh": "这些法律使政治气候降温，而霍姆斯关于明显而即刻危险的追问开启了20世纪言论自由与公民自由的法律斗争。", "src": {"text": "incite, provoke, or encourage resistance to the United States, or promote the cause of its enemies.", "attr": "Sedition Act of 1918"}, "exp_en": "The wartime speech laws jailed over a thousand dissenters and set the terms for every later American debate about security versus free speech.", "exp_zh": "战时言论法监禁了上千名异议者，为后来美国每一次安全与言论自由之争定下了基调。", "page": 691, "img": {"file": "img:f2_918", "credit": "图源：Henretta《America's History》第8版 p.691"}}, {"id": "p7-013", "period": 7, "topic_en": "Great Migration", "topic_zh": "大迁徙", "year": null, "year_text": "1910s (accelerated during World War I)", "who": [], "who_zh": [], "what_en": "World War I created tremendous economic opportunities at home, and wartime labor shortages opened heavy-industry jobs to African Americans for the first time. During the war more than 400,000 African Americans moved from the South to northern cities such as St. Louis, Chicago, New York, and Detroit in what became known as the Great Migration; northern manufacturers sent labor agents to the South to recruit workers.", "what_zh": "一战在国内创造了巨大经济机会，战时劳动力短缺首次向非裔美国人敞开重工业岗位。战争期间40多万非裔从南方迁往圣路易斯、芝加哥、纽约、底特律等北方城市，即大迁徙；北方制造商派劳工代理人到南方招工。", "cause_en": "Wartime jobs and labor shortages with so many men in uniform, plus the desire to escape the repressive racism and poverty of the South.", "cause_zh": "大量男子参军造成的战时岗位和劳动力短缺，以及逃离南方压迫性种族主义和贫困的愿望。", "sig_en": "It transformed northern cities, built black community institutions and economic and voting clout, and laid the groundwork for the Harlem Renaissance and postwar racial conflict.", "sig_zh": "它改变了北方城市，建立了黑人社区机构和经济、选票影响力，为哈莱姆文艺复兴和战后种族冲突奠定基础。", "exp_en": "The Great Migration was the wartime movement of Black southerners to northern industry that remade American cities and Black political power.", "exp_zh": "大迁徙是战时南方黑人向北方工业的迁移，重塑了美国城市和黑人政治力量。", "page": 694, "img": {"file": "img:f2_926", "credit": "图源：Henretta《America's History》第8版 p.694"}}, {"id": "p7-014", "period": 7, "topic_en": "National Woman's Party and the Nineteenth Amendment", "topic_zh": "全国妇女党与第十九修正案", "year": 1920, "year_text": "ratified August 26, 1920", "who": ["Alice Paul", "Carrie Chapman Catt", "Woodrow Wilson"], "who_zh": ["爱丽丝·保罗", "卡丽·查普曼·卡特", "伍德罗·威尔逊"], "what_en": "Alice Paul founded the National Woman's Party in 1916 and, inspired by militant British suffragists, began picketing the White House in July 1917; activists were jailed for seven months, hunger-struck, and were force-fed. Impressed by NAWSA's wartime patriotism and worried by the NWP's militancy, Wilson reversed his position in January 1918, urging suffrage as a war measure. On August 26, 1920, Tennessee's ratification made the Nineteenth Amendment law.", "what_zh": "爱丽丝·保罗1916年创立全国妇女党，受英国激进妇女参政运动启发，1917年7月起在白宫外纠察；活动家被监禁七个月、绝食并遭强行喂食。威尔逊被全国妇女参政协会的战时爱国表现打动，又担心全国妇女党的激进，1918年1月转变立场，呼吁把妇女参政作为战争措施。1920年8月26日田纳西州批准，第十九修正案生效。", "cause_en": "Decades of suffrage organizing plus wartime service by women and the public shock at the militant suffragists' treatment.", "cause_zh": "数十年的参政运动，加上妇女的战时贡献和公众对激进参政者遭遇的震惊。", "sig_en": "Women won national voting rights, though in the Jim Crow South African American women's voting rights remained restricted along with men's.", "sig_zh": "妇女赢得全国投票权，但在实行吉姆·克劳法的南方，非裔妇女的投票权仍与男子一样受限。", "exp_en": "Militant pickets plus wartime patriotism forced Wilson's hand: the Nineteenth Amendment enfranchised American women in 1920.", "exp_zh": "激进纠察加战时爱国表现迫使威尔逊让步：第十九修正案1920年赋予美国妇女投票权。", "page": 695, "img": {"file": "img:f2_928", "credit": "图源：Henretta《America's History》第8版 p.695"}}, {"id": "p7-015", "period": 7, "topic_en": "Fourteen Points, Treaty of Versailles, and Senate rejection", "topic_zh": "十四点原则、凡尔赛条约与参议院否决", "year": 1919, "year_text": "Fourteen Points 1918; Treaty 1919; Senate rejects November 1919 and March 1920", "who": ["Woodrow Wilson", "Henry Cabot Lodge", "Georges Clemenceau", "David Lloyd George"], "who_zh": ["伍德罗·威尔逊", "亨利·卡伯特·洛奇", "乔治·克列孟梭", "大卫·劳合·乔治"], "what_en": "Wilson's Fourteen Points (1918) called for open diplomacy, freedom of the seas, arms reduction, removal of trade barriers, national self-determination, and a League of Nations with collective security under Article X. At Versailles (1919), Britain and France imposed harsh terms on Germany: $33 billion in reparations plus territory and resource losses. Nine new European nations were created, but colonized peoples stayed subordinate. At home, irreconcilables and Lodge's reservationists blocked ratification; Wilson refused amendments and suffered a stroke in September 1919; the treaty failed in November 1919 and March 1920, and the United States never joined the League.", "what_zh": "威尔逊1918年十四点原则主张公开外交、海洋自由、裁军、消除贸易壁垒、民族自决，以及按第十条实行集体安全的国际联盟。1919年凡尔赛会议上英法对德国强加苛刻条款：330亿美元赔款及领土资源损失。九个欧洲新国家按自决原则建立，但殖民地人民仍受压制。国内不可调和派和洛奇的保留派阻挠批准；威尔逊拒绝修正案并于1919年9月中风；条约1919年11月和1920年3月两度未获通过，美国从未加入国联。", "cause_en": "Wilson's idealist bid for peace among equals; Allied determination to punish Germany; Senate fears that Article X would let an international body order American youth to war.", "cause_zh": "威尔逊对平等和平的理想主义追求；协约国惩罚德国的决心；参议院担心第十条会让国际机构命令美国青年参战。", "sig_en": "The United States turned its back on Wilson's international order, weakening the League, and the treaty's harsh terms fueled German resentment that helped lead to World War II.", "sig_zh": "美国背弃威尔逊的国际秩序，削弱了国联；条约的苛刻条款激起德国怨恨，助长了二战的爆发。", "src": {"text": "all-powerful, all-ignorant men, sitting there and carving up continents.", "attr": "Arthur Balfour"}, "exp_en": "Wilson won the peace conference but lost the Senate: the Versailles treaty's punishment of Germany and America's rejection of the League shaped the next twenty years.", "exp_zh": "威尔逊赢了和会却输了参议院：凡尔赛条约对德国的惩罚和美国对国联的拒绝塑造了此后二十年。", "page": 697, "img": {"file": "img:f2_933", "credit": "图源：Henretta《America's History》第8版 p.697"}}, {"id": "p7-016", "period": 7, "topic_en": "Red Scare and Palmer raids", "topic_zh": "红色恐慌与帕尔默大搜捕", "year": 1919, "year_text": "1919-1920", "who": ["A. Mitchell Palmer", "J. Edgar Hoover"], "who_zh": ["A·米切尔·帕尔默", "J·埃德加·胡佛"], "what_en": "After mail bombs in April 1919 and a bomb at Attorney General A. Mitchell Palmer's home, Palmer fanned public fears of Bolsheviks (Reds). He set up an antiradical division and appointed his assistant J. Edgar Hoover to direct it; it soon became the FBI. In November 1919 agents stormed radical headquarters and deported aliens without trial; on a notorious night in January 1920 agents arrested six thousand citizens and aliens and denied them counsel. Palmer's predicted May 1 uprising never happened, and the scare abated.", "what_zh": "1919年4月邮包炸弹和司法部长帕尔默家门口的炸弹之后，帕尔默煽动公众对布尔什维克（红色分子）的恐惧。他设立反激进部门，任命助理胡佛领导，即后来的联邦调查局。1919年11月特工突袭激进组织总部，未经审判驱逐外侨；1920年1月一个臭名昭著的夜晚逮捕六千公民和外侨并拒绝其律师帮助。帕尔默预言的五一暴动从未发生，恐慌消退。", "cause_en": "Fear of Bolshevism after Russia's revolution and the founding of the Third International (1919); wartime hatred of Germans redirected at Reds; postwar strikes and 80 percent inflation.", "cause_zh": "俄国革命和第三国际成立（1919）引发对布尔什维克的恐惧；战时对德国人的仇恨转向红色分子；战后罢工和80%的通胀。", "sig_en": "The FBI was born from Palmer's antiradical division, and antiradicalism endured, feeding cases like Sacco and Vanzetti and prompting the ACLU's founding to defend free speech.", "sig_zh": "联邦调查局诞生于帕尔默的反激进部门，反激进主义延续下来，助长了萨科-范泽蒂案等事件，并促使美国公民自由联盟成立以捍卫言论自由。", "exp_en": "The Red Scare turned wartime loyalty campaigns into a peacetime hunt for radicals, creating the FBI and a lasting culture of antiradicalism.", "exp_zh": "红色恐慌把战时的忠诚运动变成和平时期的激进分子猎捕，催生了联邦调查局和持久的反激进文化。", "page": 708, "img": {"file": "img:f2_961", "credit": "图源：Henretta《America's History》第8版 p.708"}}, {"id": "p7-017", "period": 7, "topic_en": "Sacco and Vanzetti", "topic_zh": "萨科与范泽蒂案", "year": 1927, "year_text": "arrested 1920; executed 1927", "who": ["Nicola Sacco", "Bartolomeo Vanzetti"], "who_zh": ["尼古拉·萨科", "巴托洛梅奥·范泽蒂"], "what_en": "In May 1920, at the height of the Red Scare, police arrested Nicola Sacco, a shoemaker, and Bartolomeo Vanzetti, a fish peddler, for a robbery-murder at a South Braintree, Massachusetts shoe company. The two Italian immigrants and self-proclaimed anarchists were convicted; they sat in jail for six years during appeals, and in 1927 Judge Webster Thayer denied a new trial and they were executed. Scholars still debate their guilt, but prosecutors had emphasized their radical ties.", "what_zh": "1920年5月红色恐慌高潮时，警方逮捕了鞋匠萨科和鱼贩范泽蒂，指控他们在马萨诸塞州南布伦特里一家鞋厂抢劫杀人。这两名意大利移民、自称无政府主义者被定罪，在狱中等待上诉六年；1927年韦伯斯特·塞耶法官拒绝重审，两人被处决。学者至今争论其有罪与否，但检方一直强调他们的激进背景。", "cause_en": "The ethnic and political hostilities of the Red Scare era and nativist prejudice against Italian immigrants.", "cause_zh": "红色恐慌时代的族裔与政治敌意，以及对意大利移民的排外偏见。", "sig_en": "Their execution became one of the ugly scars left by the ethnic and political hostilities of the Great War era.", "sig_zh": "他们的处决成为大战时代族裔与政治敌意留下的丑陋伤疤之一。", "exp_en": "Sacco and Vanzetti's biased trial and execution made them international symbols of Red Scare injustice.", "exp_zh": "萨科和范泽蒂充满偏见的审判与处决使他们成为红色恐慌不公的国际象征。", "page": 709}, {"id": "p7-018", "period": 7, "topic_en": "Teapot Dome scandal", "topic_zh": "茶壶山丑闻", "year": 1923, "year_text": "scandal revealed 1923", "who": ["Warren G. Harding", "Albert Fall", "Calvin Coolidge"], "who_zh": ["沃伦·G·哈定", "阿尔伯特·福尔", "卡尔文·柯立芝"], "what_en": "The worst Harding-administration scandal concerned the secret leasing of government oil reserves at Teapot Dome, Wyoming, and Elk Hills, California, to private companies. Secretary of the Interior Albert Fall was eventually convicted of taking $300,000 in bribes and became the first cabinet officer in U.S. history to serve a prison sentence. The evidence emerged just as Harding died suddenly of a heart attack in August 1923.", "what_zh": "哈定政府最严重的丑闻是把怀俄明州茶壶山和加州麋鹿山的政府石油储备秘密租给私人公司。内政部长阿尔伯特·福尔最终因受贿30万美元被定罪，成为美国历史上第一位服刑的内阁部长。证据浮现时，哈定正好1923年8月突发心脏病去世。", "cause_en": "Cronyism in Harding's probusiness administration and corrupt links between government officials and corporate interests.", "cause_zh": "哈定亲商政府中的任人唯亲，以及政府官员与企业利益之间的腐败勾结。", "sig_en": "Teapot Dome became the emblem of 1920s government-corporate corruption; Coolidge succeeded Harding and offered a contrast of austere Yankee morality.", "sig_zh": "茶壶山成为1920年代官商腐败的象征；柯立芝继任，以严谨的扬基道德与哈定形成对比。", "exp_en": "Teapot Dome exposed how the 1920s associated state slid into bribery, sending a cabinet secretary to prison for the first time.", "exp_zh": "茶壶山暴露了1920年代协作国家如何滑向贿赂，首次把内阁部长送进监狱。", "page": 710, "img": {"file": "img:f2_968", "credit": "图源：Henretta《America's History》第8版 p.710"}}, {"id": "p7-019", "period": 7, "topic_en": "Sheppard-Towner Act", "topic_zh": "谢泼德-汤纳法案", "year": 1921, "year_text": "1921", "who": [], "who_zh": [], "what_en": "The Sheppard-Towner Federal Maternity and Infancy Act (1921), the greatest accomplishment of the Women's Joint Congressional Committee, was the first federally funded health-care legislation. It provided federal funds for medical clinics, prenatal education programs, and visiting nurses, significantly lowered infant mortality rates, and marked the first time Congress gave federal funds to states to run a social welfare program. Congress ended the program in the late 1920s.", "what_zh": "1921年《谢泼德-汤纳联邦妇婴法案》是妇女联合国会委员会的最大成就，也是第一部联邦资助的医疗立法。它为诊所、产前教育和巡回护士提供联邦资金，显著降低婴儿死亡率，是国会首次拨款给各州推行社会福利项目。国会在1920年代末终止了该项目。", "cause_en": "Post-suffrage hopes that women's votes would leverage new reforms, and progressive concern for maternal and infant health.", "cause_zh": "妇女获得选举权后希望选票能推动新改革，以及进步派对妇婴健康的关注。", "sig_en": "It was a landmark first federal welfare grant, but its repeal showed how limited women's reform gains were in the 1920s.", "sig_zh": "它是联邦福利拨款的里程碑式开端，但其被废除表明1920年代妇女改革成果何其有限。", "exp_en": "Sheppard-Towner was the first time Washington paid states to deliver welfare, a breakthrough Congress soon abandoned.", "exp_zh": "谢泼德-汤纳法案是华盛顿首次出钱让各州提供福利的突破，而国会很快就放弃了它。", "page": 709}, {"id": "p7-020", "period": 7, "topic_en": "Dollar diplomacy", "topic_zh": "金元外交", "year": null, "year_text": "1920s (term coined 1924)", "who": ["Samuel Guy Inman"], "who_zh": ["塞缪尔·盖伊·英曼"], "what_en": "In the 1920s Republican presidents advanced U.S. business interests by encouraging private banks to make foreign loans, backed by State Department pressure and military force. The Marines occupied Nicaragua almost continuously from 1912 to 1933, the Dominican Republic from 1916 to 1924, and Haiti from 1915 to 1934. The loans often ended up in local elites' pockets, and occupations helped produce harsh dictatorships, as in Haiti.", "what_zh": "1920年代共和党总统鼓励私人银行向外放贷，以国务院施压和军事力量为后盾，推进美国商业利益。海军陆战队几乎连续占领尼加拉瓜（1912-1933）、多米尼加（1916-1924）和海地（1915-1934）。贷款常落入当地精英口袋，占领还助长了残暴独裁，如海地。", "cause_en": "The Republican associated state alliance of government and business; bankers wanted guaranteed loans and policymakers wanted markets for U.S. products.", "cause_zh": "共和党协作国家中政府与企业的联盟；银行家要贷款担保，决策者要美国产品的市场。", "sig_en": "Critics led by missionary Samuel Guy Inman, who coined the term dollar diplomacy in 1924, denounced the destruction of other peoples' sovereignty; by the late 1920s the policy was on the defensive.", "sig_zh": "传教士塞缪尔·盖伊·英曼1924年创造金元外交一词，批评者谴责其摧残弱小国家主权；到1920年代末该政策已处于守势。", "exp_en": "Dollar diplomacy used bankers' loans and Marines' bayonets to serve American business abroad, breeding resentment and dictatorship.", "exp_zh": "金元外交用银行家的贷款和海军陆战队的刺刀为美国企业在海外服务，播下怨恨和独裁的种子。", "page": 711}, {"id": "p7-021", "period": 7, "topic_en": "Prohibition", "topic_zh": "禁酒令", "year": 1920, "year_text": "Eighteenth Amendment takes effect January 1920", "who": ["Al Capone"], "who_zh": ["阿尔·卡彭"], "what_en": "The decades-long temperance campaign culminated in the Eighteenth Amendment, passed by Congress in 1917 and taking effect in January 1920, which prohibited the manufacture, sale, or transportation of intoxicating liquors. In cities thousands ignored the law: speakeasies flourished and gangsters such as Chicago's Al Capone profited. Enforcement difficulties contributed to repeal in 1933.", "what_zh": "数十年的禁酒运动在1917年国会通过、1920年1月生效的第十八修正案达到顶峰，禁止酿造、销售或运输烈酒。城市中数千人公然违法：地下酒吧林立，芝加哥的阿尔·卡彭等黑帮获利。执法困难促成1933年废除。", "cause_en": "The rural Protestant moral crusade, wartime anti-German prejudice (breweries like Pabst and Anheuser-Busch were German-American-owned), and wartime limits on brewers' grain use.", "cause_zh": "乡村新教徒的道德圣战、战时反德偏见（Pabst、安海斯-布希等啤酒厂为德裔美国人所有），以及战时对酿酒用粮的限制。", "sig_en": "Prohibition showed religion's power over public policy, but its unenforceability made it a symbol of the culture wars and enriched organized crime.", "sig_zh": "禁酒令显示了宗教对公共政策的影响力，但其无法执行使其成为文化战争的象征，并肥了有组织犯罪。", "src": {"text": "manufacture, sale, or transportation of intoxicating liquors", "attr": "Eighteenth Amendment"}, "exp_en": "Prohibition turned a Protestant moral crusade into constitutional law, then into a nationwide lesson in unenforceability.", "exp_zh": "禁酒令把新教徒的道德圣战写进宪法，又变成全国性的无法执行之课。", "page": 712, "img": {"file": "img:f2_973", "credit": "图源：Henretta《America's History》第8版 p.712"}}, {"id": "p7-022", "period": 7, "topic_en": "Scopes trial", "topic_zh": "斯科普斯审判", "year": 1925, "year_text": "1925", "who": ["John T. Scopes", "Clarence Darrow", "William Jennings Bryan"], "who_zh": ["约翰·T·斯科普斯", "克拉伦斯·丹诺", "威廉·詹宁斯·布莱恩"], "what_en": "In 1925 Tennessee outlawed teaching any theory that denies the biblical account of creation. The ACLU, formed during the Red Scare to protect free speech, challenged the law in the trial of high school biology teacher John T. Scopes, who had taught evolution. Clarence Darrow defended Scopes while three-time Democratic presidential candidate William Jennings Bryan spoke for the prosecution. The monkey trial was broadcast live on Chicago radio; the jury took eight minutes to convict, though the state supreme court later overturned the conviction while the law stayed on the books for thirty more years.", "what_zh": "1925年田纳西州立法禁止教授任何否认圣经创世说的理论。红恐时期为捍卫言论自由成立的美国公民自由联盟，在教授进化论的高中生物教师斯科普斯案中挑战该法。丹诺为斯科普斯辩护，三度民主党总统候选人布莱恩代表控方。猴子审判通过芝加哥电台直播；陪审团八分钟定罪，州最高法院后来推翻定罪，但法律又保留了三十多年。", "cause_en": "Fundamentalist Protestants versus modernism; the rural-urban cultural conflict of the 1920s.", "cause_zh": "基要派新教徒与现代主义之争；1920年代城乡文化冲突。", "sig_en": "The trial became the iconic clash of the 1920s culture wars over religion's place in public life and schools.", "sig_zh": "该审判成为1920年代文化战争中宗教在公共生活和学校中地位的标志性对决。", "exp_en": "The Scopes monkey trial put evolution, the Bible, and modernity itself on trial before a national radio audience.", "exp_zh": "斯科普斯猴子审判把进化论、圣经和现代性本身送上被告席，面对全国广播听众。", "page": 713}, {"id": "p7-023", "period": 7, "topic_en": "National Origins Act", "topic_zh": "1924年国籍来源法", "year": 1924, "year_text": "1924", "who": ["Calvin Coolidge"], "who_zh": ["卡尔文·柯立芝"], "what_en": "The National Origins Act (1924) used backdated census data to cap each country's annual immigration at 2 percent of that nationality's share of the U.S. population in 1890, drastically limiting immigration from Southern and Eastern Europe (Italians, Greeks, Poles, Russians). In 1929 Congress imposed even tighter quotas: 150,000 per year from Europe and continued bans on most Asian immigrants. Western Hemisphere immigration stayed unrestricted, so Mexican migration grew, and the Border Patrol was established.", "what_zh": "1924年《国籍来源法》用回溯的人口普查数据，把每国年移民限额定为该族裔1890年在美人口占比的2%，大幅限制南欧东欧（意大利、希腊、波兰、俄国）移民。1929年国会进一步收紧：欧洲每年15万名额，多数亚洲移民继续被禁。西半球移民不受限，墨西哥移民增长，边境巡逻队成立。", "cause_en": "Nativism: Coolidge declared America must be kept American; native-born Protestants called Southern and Eastern Europeans indigestible lumps and feared imported radicalism and Catholicism.", "cause_zh": "排外主义：柯立芝宣称美国必须保持美国性；本土新教徒称南欧东欧人为难消化的硬块，担心输入激进主义和天主教。", "sig_en": "It was the most sweeping immigration restriction in U.S. history to that point, reshaping the nation's ethnic composition for four decades.", "sig_zh": "它是当时美国历史上最彻底的移民限制，重塑了此后四十年的族裔构成。", "src": {"text": "America must be kept American.", "attr": "Calvin Coolidge"}, "exp_en": "The National Origins Act wrote nativist prejudice into quotas, nearly closing America's doors to Southern and Eastern Europeans and Asians.", "exp_zh": "国籍来源法把排外偏见写进配额，几乎对南欧东欧人和亚洲人关闭了美国大门。", "page": 713}, {"id": "p7-024", "period": 7, "topic_en": "Second Ku Klux Klan", "topic_zh": "第二代三K党", "year": 1915, "year_text": "revived 1915; peaked mid-1920s", "who": [], "who_zh": [], "what_en": "After the premiere of Birth of a Nation (1915), which glorified the Reconstruction-era Klan, southerners gathered on Georgia's Stone Mountain to revive the Ku Klux Klan. With the motto Native, white, Protestant supremacy, the 1920s Klan targeted not only Blacks but immigrants, Catholics, and Jews with intimidation, arson, and boycotts. At its height it counted more than three million members with serious political clout. It declined nationally after 1925, robbed of its issue by the 1924 immigration law, but stayed strong in the South.", "what_zh": "1915年美化重建时期三K党的《一个国家的诞生》上映后，南方人在佐治亚州石山重建三K党。以本土、白人、新教徒至上为口号，1920年代的三K党不仅针对黑人，还恐吓、纵火、抵制移民、天主教徒和犹太人。鼎盛时成员超三百万，政治影响力巨大。1925年后因1924年移民法夺去其议题而在全国衰落，但在南方依然强大。", "cause_en": "Postwar racial and religious anxieties, nativism, and the cultural power of Birth of a Nation.", "cause_zh": "战后种族与宗教焦虑、排外主义，以及《一个国家的诞生》的文化影响力。", "sig_en": "It showed how deeply white supremacy and nativism penetrated 1920s politics and helped prepare the way for 1930s white-supremacist movements like the Silver Legion.", "sig_zh": "它显示白人至上和排外主义渗透1920年代政治之深，并为1930年代银衫军等白人至上运动铺路。", "src": {"text": "Native, white, Protestant supremacy", "attr": "Ku Klux Klan motto"}, "exp_en": "The 1920s Klan was a nationwide mass movement of native white Protestantism, not just a southern terror group.", "exp_zh": "1920年代的三K党是本土白人新教徒的全国性群众运动，而不只是南方的恐怖组织。", "page": 714, "img": {"file": "img:f2_977", "credit": "图源：Henretta《America's History》第8版 p.714"}}, {"id": "p7-025", "period": 7, "topic_en": "Warren G. Harding and normalcy", "topic_zh": "哈定与常态回归", "year": 1920, "year_text": "1920", "who": ["Warren G. Harding"], "who_zh": ["沃伦·G·哈定"], "what_en": "In 1920 Republicans tapped genial Ohio senator Warren G. Harding, who promised not nostrums but normalcy, a dig at Wilson's idealism. He won in a landslide, beginning an era of Republican dominance that lasted until 1932, with administrations that placed the nation's well-being in the hands of business and pursued limited government.", "what_zh": "1920年共和党提名和蔼的俄亥俄州参议员哈定，他承诺不要万灵药、要常态，讽刺威尔逊的理想主义。他以压倒性优势获胜，开启持续到1932年的共和党主导时代；其政府把国家福祉交给企业，推行小政府。", "cause_en": "Postwar exhaustion with Wilsonian reform and internationalism; Americans wanted prosperity, not progressivism.", "cause_zh": "战后对威尔逊式改革和国际主义的厌倦；美国人要繁荣，不要进步主义。", "sig_en": "Normalcy defined the 1920s Republican era of hands-off government, whose policies the book argues likely helped trigger the Great Depression and deepened it.", "sig_zh": "常态定义了1920年代共和党不干预政府的时代，其政策据本书认为可能引发大萧条并加深其危害。", "why_term": "normalcy", "why_term_q": "Harding's 1920 campaign promise was not nostrums but ______.", "src": {"text": "not nostrums but normalcy.", "attr": "Warren G. Harding"}, "exp_en": "Harding's normalcy was the 1920s promise to trade Wilson's crusades for business-led calm, the creed of the Republican decade.", "exp_zh": "哈定的常态是1920年代的承诺：用企业主导的平静取代威尔逊的圣战，成为共和党十年的信条。", "page": 710, "img": {"file": "img:f2_968", "credit": "图源：Henretta《America's History》第8版 p.710"}}, {"id": "p7-026", "period": 7, "topic_en": "Harlem Renaissance", "topic_zh": "哈莱姆文艺复兴", "year": null, "year_text": "1920s (peaked mid-1920s)", "who": ["Langston Hughes", "Zora Neale Hurston", "Alain Locke", "Louis Armstrong", "Jacob Lawrence"], "who_zh": ["兰斯顿·休斯", "佐拉·尼尔·赫斯顿", "阿兰·洛克", "路易斯·阿姆斯特朗", "雅各布·劳伦斯"], "what_en": "The Great Migration tripled New York's Black population in the decade after 1910, and Harlem became the symbol of liberty and the Promised Land. Writers like Langston Hughes, Zora Neale Hurston, Claude McKay, and Jean Toomer, artists like Jacob Lawrence, and jazz musicians led by Louis Armstrong created bold new art forms asserting race pride and ties to Africa. Jazz became the era's signature music, so much so that F. Scott Fitzgerald dubbed the 1920s the Jazz Age.", "what_zh": "大迁徙使1910年后十年纽约黑人人口增至三倍，哈莱姆成为自由与应许之地的象征。兰斯顿·休斯、赫斯顿、麦凯、图默等作家，雅各布·劳伦斯等画家，以及阿姆斯特朗领衔的爵士乐手，创造了大胆的新艺术形式，宣示种族自豪和与非洲的联系。爵士乐成为时代标志，菲茨杰拉德称1920年代为爵士时代。", "cause_en": "The Great Migration's concentration of Black talent, audiences, and institutions in northern cities, plus postwar determination to assert citizenship rights.", "cause_zh": "大迁徙把黑人人才、观众和机构集中到北方城市，加上战后争取公民权的决心。", "sig_en": "It brought Black music and art to the center of American culture and inspired pan-African political consciousness.", "sig_zh": "它把黑人音乐和艺术带到美国文化中心，并激发了泛非政治意识。", "src": {"text": "I am a Negro - and beautiful.", "attr": "Langston Hughes"}, "exp_en": "The Harlem Renaissance turned the Great Migration's urban Black communities into the engine of a cultural revolution in art, literature, and jazz.", "exp_zh": "哈莱姆文艺复兴把大迁徙形成的城市黑人社区变成艺术、文学和爵士乐文化革命的引擎。", "page": 718, "img": {"file": "img:f2_987", "credit": "图源：Henretta《America's History》第8版 p.718"}}, {"id": "p7-027", "period": 7, "topic_en": "Marcus Garvey and the UNIA", "topic_zh": "马库斯·加维与世界黑人进步协会", "year": null, "year_text": "1920s (Garvey imprisoned 1925)", "who": ["Marcus Garvey"], "who_zh": ["马库斯·加维"], "what_en": "The Harlem-based Universal Negro Improvement Association (UNIA), led by charismatic Jamaican-born Marcus Garvey, arose in the 1920s to mobilize African American workers and champion Black separatism. Garvey urged followers to move to Africa, arguing people of African descent would never be treated justly in white-run countries. The UNIA claimed four million followers, published Negro World, and created the Black Star steamship line. In 1925 Garvey was imprisoned for mail fraud; Coolidge commuted his sentence but deported him to Jamaica, and the movement collapsed.", "what_zh": "1920年代，牙买加出生的加维领导哈莱姆的世界黑人进步协会，动员非裔工人，主张黑人分离主义。加维敦促追随者迁往非洲，认为非洲后裔在白人统治的国家永不得公正对待。协会号称四百万成员，出版《黑人世界报》，创建黑星航运公司。1925年加维因邮件欺诈入狱，柯立芝减刑但将其驱逐到牙买加，运动随之瓦解。", "cause_en": "Postwar racial violence and disappointment with integration; the belief that justice was impossible in white-run countries.", "cause_zh": "战后种族暴力和对融合的失望；认为在白人统治国家不可能获得公正。", "sig_en": "Garvey left a legacy of activism and pan-Africanism: the idea that people of African descent worldwide share a common destiny and should cooperate politically.", "sig_zh": "加维留下行动主义和泛非主义遗产：世界各地非洲后裔命运相同、应在政治上合作的理念。", "exp_en": "Garvey's UNIA was the mass movement that made Black nationalism and pan-Africanism a force in 1920s America, even after his deportation.", "exp_zh": "加维的世界黑人进步协会是让黑人民族主义和泛非主义成为1920年代美国力量的群众运动，即便在他被驱逐之后。", "page": 719, "img": {"file": "img:f2_994", "credit": "图源：Henretta《America's History》第8版 p.719"}}, {"id": "p7-028", "period": 7, "topic_en": "Lost Generation", "topic_zh": "迷惘的一代", "year": null, "year_text": "1920s", "who": ["Gertrude Stein", "Ernest Hemingway", "John Dos Passos", "Sinclair Lewis", "F. Scott Fitzgerald"], "who_zh": ["格特鲁德·斯泰因", "欧内斯特·海明威", "约翰·多斯·帕索斯", "辛克莱·刘易斯", "F·司各特·菲茨杰拉德"], "what_en": "The horrors of World War I prompted intellectuals to question civilization and progress. Gertrude Stein dubbed those who survived it the Lost Generation. John Dos Passos railed at Mr. Wilson's war in The Three Soldiers (1921); Hemingway's A Farewell to Arms (1929) portrayed war's futility; Sinclair Lewis's Babbitt (1922) savaged small-town conformity (Lewis became the first American Nobel laureate in literature in 1930); Fitzgerald's The Great Gatsby (1925) indicted the mindless pursuit of pleasure and wealth.", "what_zh": "一战的恐怖促使知识分子质疑文明与进步。斯泰因把幸存者称为迷惘的一代。多斯·帕索斯在《三个士兵》（1921）中痛斥威尔逊的战争；海明威《永别了，武器》（1929）描写战争的徒劳；刘易斯《巴比特》（1922）辛辣讽刺小镇循规蹈矩（1930年成为首位获诺贝尔文学奖的美国人）；菲茨杰拉德《了不起的盖茨比》（1925）谴责对享乐和财富的盲目追逐。", "cause_en": "The searing firsthand experience of World War I and disillusionment with prewar ideals of progress and Western superiority.", "cause_zh": "一战的切身创伤，以及对战前进步和西方优越理想的幻灭。", "sig_en": "These writers created the modernist critique of American materialism, conformity, and hypocrisy that defined 1920s intellectual culture.", "sig_zh": "这些作家创造了现代主义对美国物质主义、循规蹈矩和虚伪的批判，定义了1920年代知识文化。", "exp_en": "The Lost Generation writers turned wartime disillusionment into the defining literature of the 1920s, from Gatsby to A Farewell to Arms.", "exp_zh": "迷惘的一代作家把战时幻灭变成1920年代的代表性文学，从《盖茨比》到《永别了，武器》。", "page": 720, "img": {"file": "img:f2_997", "credit": "图源：Henretta《America's History》第8版 p.720"}}, {"id": "p7-029", "period": 7, "topic_en": "Automobile and consumer credit", "topic_zh": "汽车与消费信贷", "year": null, "year_text": "1920s (by 1929: 23 million cars)", "who": [], "who_zh": [], "what_en": "By 1929 Americans owned 23 million cars, about 80 percent of the world's automobiles. Families stretched incomes through auto loans and installment plans: Buy now, pay later. Consumer lending topped $7 billion in 1927, becoming the tenth-largest business. The auto boom created 3.7 million jobs and spurred steel, petroleum, rubber, and highway construction, but most cars were bought on credit, so defaults left banks holding unpaid loans, a factor in the 1929 bust.", "what_zh": "到1929年美国人拥有2300万辆汽车，约占世界汽车的80%。家庭靠汽车贷款和分期付款拉长收入：先买后付。1927年消费信贷超70亿美元，成为第十大产业。汽车热创造370万就业，带动钢铁、石油、橡胶和公路建设，但多数汽车靠信贷购买，违约使银行背上坏账，成为1929年崩盘的因素之一。", "cause_en": "Mass production, rising incomes, and the advertising industry's aggressive hard sell: Sell them their dreams.", "cause_zh": "大规模生产、收入上升，以及广告业的强势硬销：把梦想卖给他们。", "sig_en": "The automobile revolutionized leisure, sprawl, and daily life, while credit-fueled consumption made the whole economy fragile.", "sig_zh": "汽车革新了休闲、城市蔓延和日常生活，而信贷助长的消费使整个经济变得脆弱。", "exp_en": "The car was the 1920s showpiece of consumer capitalism: freedom on installment plans, until the credit ran out in 1929.", "exp_zh": "汽车是1920年代消费资本主义的招牌：分期付款的自由，直到1929年信贷断裂。", "page": 725, "img": {"file": "img:f2_1014", "credit": "图源：Henretta《America's History》第8版 p.725"}}, {"id": "p7-030", "period": 7, "topic_en": "Stock market crash of 1929", "topic_zh": "1929年股市崩盘", "year": 1929, "year_text": "October-November 1929", "who": [], "who_zh": [], "what_en": "By 1927 strains showed: unrealistic expectations, margin buying (an investor might put $20 down and borrow $80 for a $100 share), and corporations plowing profits into stocks. Between October 25 and November 13, 1929 the market plunged in a series of falls. Over the next four years industrial production fell 37 percent, construction 78 percent, crop prices halved, and by 1932 unemployment reached 24 percent; uninsured bank deposits vanished in waves of bank failures.", "what_zh": "1927年已现裂痕：不切实际的预期、保证金交易（投20美元借80美元买100美元股票）、企业把利润投入股市。1929年10月25日至11月13日股市连番暴跌。此后四年工业生产降37%，建筑降78%，农产品价格腰斩，1932年失业率达24%；银行成批倒闭，无保险的存款化为乌有。", "cause_en": "Easy credit, speculation, margin buying, weak agriculture, maldistributed income, and interconnected global conditions; the book argues 1920s Republican policies likely helped trigger the Depression.", "cause_zh": "宽松信贷、投机、保证金交易、农业疲弱、收入分配不均，以及相互关联的全球条件；本书认为1920年代共和党政策可能引发了大萧条。", "sig_en": "The crash ended the Roaring Twenties, discredited probusiness Republican policies, and set up the 1932 Democratic landslide and the New Deal.", "sig_zh": "崩盘终结了咆哮的二十年代，使亲商的共和党政策信誉扫地，并促成1932年民主党大胜和新政。", "exp_en": "The 1929 crash turned a speculative bubble built on margin and credit into the Great Depression that remade American government.", "exp_zh": "1929年崩盘把建立在保证金和信贷上的投机泡沫变成重塑美国政府的大萧条。", "page": 727}, {"id": "p7-031", "period": 7, "topic_en": "Smoot-Hawley Tariff", "topic_zh": "斯穆特-霍利关税", "year": 1930, "year_text": "1930", "who": ["Herbert Hoover"], "who_zh": ["赫伯特·胡佛"], "what_en": "In 1930 congressional Republicans enacted the Smoot-Hawley Tariff, high taxes on imported goods designed to protect American manufacturing. Despite receiving a letter from more than a thousand economists urging him to veto it, Hoover approved the legislation. Smoot-Hawley triggered retaliatory tariffs in other countries, which further hindered global trade and deepened economic contraction throughout the industrialized world.", "what_zh": "1930年国会共和党人通过《斯穆特-霍利关税法》，对进口商品征收高额关税以保护美国制造业。尽管收到一千多名经济学家的联名信敦促否决，胡佛仍签署了该法。它引发各国报复性关税，进一步阻碍全球贸易，加深了工业化世界的经济收缩。", "cause_en": "Economic orthodoxy that high tariffs protected American manufacturing, plus Hoover's adherence to traditional remedies and the gold standard.", "cause_zh": "高关税保护美国制造业的经济正统观念，以及胡佛对传统药方和金本位的坚持。", "sig_en": "It became the textbook example of a policy that worsened the Depression by choking international trade.", "sig_zh": "它成为以扼杀国际贸易而加剧大萧条的教科书式反面案例。", "exp_en": "Smoot-Hawley showed how Hoover's orthodox remedies backfired: protecting American factories strangled the world trade they depended on.", "exp_zh": "斯穆特-霍利关税表明胡佛的正统药方如何适得其反：保护美国工厂却扼杀了它们依赖的世界贸易。", "page": 736}, {"id": "p7-032", "period": 7, "topic_en": "Bonus Army", "topic_zh": "退伍军人补偿金大军", "year": 1932, "year_text": "summer 1932", "who": ["Herbert Hoover", "Douglas MacArthur"], "who_zh": ["赫伯特·胡佛", "道格拉斯·麦克阿瑟"], "what_en": "In the summer of 1932 the Bonus Army, a determined group of 15,000 unemployed World War I veterans, hitchhiked to Washington to demand immediate payment of pension awards due in 1945. They camped near the Capitol, saying We were heroes in 1917, but we're bums now. Hoover called out regular army troops under General Douglas MacArthur, who forcefully evicted the marchers and burned their main encampment. Newsreel footage of the Army attacking veterans reached movie theaters nationwide, and Hoover's popularity plunged.", "what_zh": "1932年夏，15000名失业的一战老兵组成补偿金大军，搭便车到华盛顿要求提前兑现1945年才到期的抚恤金。他们在国会山附近扎营，喊道：1917年我们是英雄，现在我们是废物。胡佛派出麦克阿瑟指挥的正规军强行驱散并烧毁营地。美军攻击老兵的新闻片传遍全国影院，胡佛声望暴跌。", "cause_en": "Depression desperation and Congress's refusal to pay the veterans' bonus early.", "cause_zh": "大萧条的绝望和国会拒绝提前支付老兵补偿金。", "sig_en": "The episode symbolized Hoover's perceived insensitivity to suffering and helped doom his reelection.", "sig_zh": "该事件象征胡佛对苦难的麻木不仁，断送了他的连任希望。", "src": {"text": "We were heroes in 1917, but we're bums now.", "attr": "Bonus Army veteran"}, "exp_en": "The Bonus Army's eviction by MacArthur's troops turned veterans' desperation into the defining image of Hoover's failed presidency.", "exp_zh": "麦克阿瑟军队驱散补偿金大军，把老兵的绝望变成胡佛失败总统任期的标志性画面。", "page": 738, "img": {"file": "img:f2_1045", "credit": "图源：Henretta《America's History》第8版 p.738"}}, {"id": "p7-033", "period": 7, "topic_en": "Election of 1932 and the Hundred Days", "topic_zh": "1932年大选与百日新政", "year": 1932, "year_text": "elected November 1932; Hundred Days March-June 1933", "who": ["Franklin Delano Roosevelt", "Herbert Hoover"], "who_zh": ["富兰克林·德拉诺·罗斯福", "赫伯特·胡佛"], "what_en": "The Democrats turned to New York governor Franklin Delano Roosevelt, who pledged vigorous action but no specifics, arguing that the country demands bold, persistent experimentation. He won easily, 22.8 million votes to Hoover's 15.7 million. In the legendary Hundred Days, Congress enacted fifteen major bills on banking failures, agricultural overproduction, the business slump, and unemployment, derided as alphabet soup for their abbreviations (CCC, WPA, AAA).", "what_zh": "民主党提名纽约州长富兰克林·罗斯福，他承诺采取有力行动但不透露细节，称国家要求大胆而持久的试验。他以2280万对1570万轻松获胜。在传奇的百日新政中，国会通过十五项重大法案，应对银行倒闭、农业过剩、工商业萧条和失业，因缩写众多（CCC、WPA、AAA）被讥为字母汤。", "cause_en": "The Depression's devastation discredited Hoover's voluntarism and limited government; Americans demanded bold action in Washington.", "cause_zh": "大萧条的重创使胡佛的自愿主义和小政府信誉扫地；美国人要求华盛顿采取大胆行动。", "sig_en": "The Hundred Days halted the downward spiral, stabilized finance, and announced a new American state: the birth of the New Deal.", "sig_zh": "百日新政止住下滑螺旋，稳定金融，宣告了一个新美国国家的诞生：新政就此开始。", "src": {"text": "the country needs and, unless I mistake its temper, the country demands bold, persistent experimentation.", "attr": "Franklin D. Roosevelt"}, "exp_en": "The 1932 election and Hundred Days converted Depression despair into the New Deal's whirlwind of federal action.", "exp_zh": "1932年大选和百日新政把大萧条的绝望变成新政联邦行动的旋风。", "page": 739, "img": {"file": "img:f2_1048", "credit": "图源：Henretta《America's History》第8版 p.739"}}, {"id": "p7-034", "period": 7, "topic_en": "Fireside chats and banking reform", "topic_zh": "炉边谈话与银行改革", "year": 1933, "year_text": "March-June 1933", "who": ["Franklin Delano Roosevelt"], "who_zh": ["富兰克林·德拉诺·罗斯福"], "what_en": "On March 5, 1933, the day after his inauguration, FDR declared a national bank holiday and Congress passed the Emergency Banking Act, letting banks reopen after Treasury inspection. In his first Sunday night fireside chat, before a radio audience of sixty million, the president reassured citizens their money was safe; when banks reopened on March 13, deposits exceeded withdrawals. The Glass-Steagall Act created the FDIC, insuring deposits up to $2,500 and barring risky investments with depositors' money. In June 1933 Roosevelt took the Treasury off the gold standard so the Federal Reserve could lower interest rates.", "what_zh": "1933年3月5日，就职次日，罗斯福宣布全国银行休假日，国会通过《紧急银行法》，经财政部检查合格的银行方可重开。在首次周日晚间炉边谈话中，他向六千万广播听众保证存款安全；3月13日银行重开时存款超过取款。《格拉斯-斯蒂格尔法》创建联邦存款保险公司，为2500美元以下存款保险，并禁止用储户资金做高风险投资。1933年6月罗斯福让财政部脱离金本位，以便美联储降息。", "cause_en": "The banking collapse: 4,000 banks failed before inauguration, and Hoover's gold-standard orthodoxy had deepened the downturn by keeping money inflexible.", "cause_zh": "银行体系崩溃：就职前4000家银行倒闭；胡佛的金本位正统使货币僵化，加深了衰退。", "sig_en": "Confidence was restored and capitalist institutions preserved: only sixty-one banks failed in all of 1934, and an advisor quipped that capitalism was saved in eight days.", "sig_zh": "信心恢复，资本主义制度得以保存：1934年全年仅61家银行倒闭，顾问戏称资本主义在八天内得救。", "src": {"text": "Capitalism was saved in eight days.", "attr": "Raymond Moley"}, "exp_en": "The bank holiday, fireside chats, and Glass-Steagall ended the banking panic and proved the federal government could rescue capitalism from itself.", "exp_zh": "银行休假日、炉边谈话和格拉斯-斯蒂格尔法终结了银行恐慌，证明联邦政府能把资本主义从自身手中拯救出来。", "page": 740}, {"id": "p7-035", "period": 7, "topic_en": "Agricultural Adjustment Act", "topic_zh": "农业调整法", "year": 1933, "year_text": "1933", "who": [], "who_zh": [], "what_en": "The Agricultural Adjustment Act (AAA) began direct governmental regulation of the farm economy for the first time. To solve overproduction, which lowered prices, it provided cash subsidies to farmers who cut production of seven major commodities: wheat, cotton, corn, hogs, rice, tobacco, and dairy products. The act briefly stabilized the farm economy, but subsidies went primarily to large and medium farm owners, who often cut production by reducing land rented to tenants and sharecroppers.", "what_zh": "《农业调整法》（AAA）首次开始对农业经济的直接政府管制。为解决压低价格的生产过剩，它向削减七大小麦、棉花、玉米、生猪、大米、烟草、奶制品产量的农民提供现金补贴。该法短暂稳定了农业经济，但补贴主要流向大中农场主，他们常通过收回佃户和分成佃农的租地来减产。", "cause_en": "Chronic agricultural overproduction had collapsed farm prices throughout the 1920s and Depression.", "cause_zh": "长期农业生产过剩使整个1920年代和大萧条期间农产品价格崩溃。", "sig_en": "It was the first federal regulation of farming, but its unequal benefits hurt Black sharecroppers and tenants; the Supreme Court voided the AAA in 1936.", "sig_zh": "它是联邦首次管制农业，但利益分配不均伤害了黑人分成佃农和佃户；最高法院1936年宣布其违宪。", "exp_en": "The AAA paid farmers not to grow crops, raising prices for owners while pushing tenants and sharecroppers off the land.", "exp_zh": "农业调整法付钱让农民不种地，抬高了农场主的价格，却把佃户和分成佃农赶出土地。", "page": 741}, {"id": "p7-036", "period": 7, "topic_en": "Civilian Conservation Corps", "topic_zh": "平民保育团", "year": 1933, "year_text": "1933", "who": [], "who_zh": [], "what_en": "The Civilian Conservation Corps (CCC) mobilized 250,000 young men to do reforestation and conservation work. Over the course of the 1930s the CCC boys built thousands of bridges, roads, trails, and other structures in state and national parks, bolstering the national infrastructure, and planted three billion trees.", "what_zh": "平民保育团（CCC）动员25万青年从事植树造林和保育工作。整个1930年代，CCC队员在州立和国家公园修建了数千座桥梁、道路、步道等设施，加强了国家基础设施，并植树三十亿棵。", "cause_en": "Massive youth unemployment and Roosevelt's conservation ideals, in the tradition of his cousin Theodore Roosevelt.", "cause_zh": "严重的青年失业和罗斯福的保育理想，延续其堂兄西奥多·罗斯福的传统。", "sig_en": "The CCC became the New Deal's most popular work program and left a permanent infrastructure legacy in parks across the country.", "sig_zh": "CCC成为新政最受欢迎的就业项目，在全国公园留下永久的基础设施遗产。", "exp_en": "The CCC put jobless young men to work healing the land, the New Deal's most beloved marriage of relief and conservation.", "exp_zh": "CCC让失业青年去治愈土地，是新政救济与保育最受爱戴的结合。", "page": 741}, {"id": "p7-037", "period": 7, "topic_en": "National Recovery Administration and Schechter", "topic_zh": "国家复兴署与谢克特案", "year": 1933, "year_text": "NRA 1933; voided in Schechter v. United States, 1935", "who": [], "who_zh": [], "what_en": "The National Industrial Recovery Act created the National Recovery Administration (NRA), which set up self-governing associations in six hundred industries; each industry regulated itself by agreeing on prices and production quotas, and businesses displayed the NRA's Blue Eagle symbol. Because large companies ran the associations, the NRA solidified their power at the expense of smaller enterprises and consumers. In Schechter v. United States (May 1935) the Supreme Court unanimously ruled the NIRA unconstitutional for delegating Congress's lawmaking power to the executive and extending federal authority to intrastate commerce.", "what_zh": "《国家工业复兴法》创建国家复兴署（NRA），在六百个行业设立自治协会；各行业通过商定价格和生产配额实行自律，企业悬挂NRA蓝鹰标志。因大公司主导协会，NRA巩固了其权力，损害小企业和消费者利益。1935年5月谢克特诉合众国案中，最高法院一致裁定该法违宪：把国会立法权授予行政部门，并把联邦权力延伸到州内贸易。", "cause_en": "Industrial underproduction and collapsing prices; the belief that coordinated planning could stabilize industry.", "cause_zh": "工业生产不足和价格崩溃；认为协调规划能稳定工业的信念。", "sig_en": "Schechter marked the Supreme Court's repudiation of early New Deal cornerstones; the Court also struck down the AAA, the Railroad Retirement Act, and the Frazier-Lemke Act.", "sig_zh": "谢克特案标志最高法院对早期新政基石的否定；法院还推翻了农业调整法、铁路退休法和弗雷泽-莱姆克法。", "exp_en": "The NRA's Blue Eagle asked business to plan itself out of the Depression; the Supreme Court killed it as an unconstitutional delegation of power.", "exp_zh": "NRA的蓝鹰要求企业靠自我规划走出萧条；最高法院以违宪的权力让渡将其扼杀。", "page": 741}, {"id": "p7-038", "period": 7, "topic_en": "Tennessee Valley Authority", "topic_zh": "田纳西河谷管理局", "year": 1933, "year_text": "1933", "who": ["Franklin Delano Roosevelt"], "who_zh": ["富兰克林·德拉诺·罗斯福"], "what_en": "Funded by Congress in 1933, the Tennessee Valley Authority (TVA) was the most extensive New Deal environmental undertaking. It integrated flood control, reforestation, electricity generation, and agricultural and industrial development; between 1933 and 1952 it built twenty dams and improved five others, taming the Tennessee River. The dams' cheap hydroelectric power brought electricity to homes, factories, and hundreds of thousands of residents, and won praise around the world.", "what_zh": "1933年国会拨款成立的田纳西河谷管理局（TVA）是新政最宏大的环境工程。它综合防洪、植树造林、发电和农工开发；1933至1952年间建造二十座大坝、改造五座，驯服田纳西河。大坝的廉价水电把电力送入家庭、工厂和数十万居民家中，赢得世界赞誉。", "cause_en": "Roosevelt saw the TVA as the first step in modernizing the South and keeping farmers on the land by improving rural life.", "cause_zh": "罗斯福把TVA视为南方现代化的第一步，希望通过改善乡村生活把农民留在土地上。", "sig_en": "It became a global model of regional planning and permanently transformed the Tennessee Valley's economy.", "sig_zh": "它成为区域规划的世界典范，永久改变了田纳西河谷的经济。", "exp_en": "The TVA was the New Deal's boldest experiment in remaking a whole region through public power and planning.", "exp_zh": "TVA是新政用公共电力和规划重塑整个地区的最大胆实验。", "page": 760, "img": {"file": "img:f2_1113", "credit": "图源：Henretta《America's History》第8版 p.760"}}, {"id": "p7-039", "period": 7, "topic_en": "Securities and Exchange Commission", "topic_zh": "证券交易委员会", "year": 1934, "year_text": "1934", "who": [], "who_zh": [], "what_en": "In 1934 Congress established the Securities and Exchange Commission (SEC) to regulate the stock market. The commission had broad powers to determine how stocks and bonds were sold to the public, to set rules for margin (credit) transactions, and to prevent stock sales by those with inside information about corporate plans.", "what_zh": "1934年国会成立证券交易委员会（SEC）监管股市。委员会有权决定股票债券如何向公众发售、制定保证金（信用）交易规则，并禁止掌握公司内幕消息者抛售股票。", "cause_en": "Reckless speculation and overleveraged buying of stocks had helped trigger the financial panic of 1929; reformers demanded Wall Street be reformed.", "cause_zh": "鲁莽投机和过度杠杆的股票买入助长了1929年金融恐慌；改革者要求整顿华尔街。", "sig_en": "It put federal regulation over securities markets for the first time, a permanent foundation for modern financial regulation.", "sig_zh": "它首次把联邦监管置于证券市场之上，成为现代金融监管的永久基石。", "exp_en": "The SEC was the New Deal's answer to 1929: Washington would police the stock market that speculation had broken.", "exp_zh": "SEC是新政对1929年的回答：华盛顿来监管被投机搞坏的股市。", "page": 745, "img": {"file": "img:f2_1068", "credit": "图源：Henretta《America's History》第8版 p.745"}}, {"id": "p7-040", "period": 7, "topic_en": "Populist critics of the New Deal", "topic_zh": "新政的民粹批评者", "year": 1934, "year_text": "1933-1935 (Share Our Wealth 1934)", "who": ["Huey Long", "Francis Townsend", "Charles Coughlin"], "who_zh": ["休伊·朗", "弗朗西斯·汤森", "查尔斯·考夫林"], "what_en": "From the populist left, critics said the New Deal had not gone far enough. Doctor Francis Townsend proposed the Old Age Revolving Pension Plan ($200 a month to citizens over sixty) and Townsend Clubs spread nationwide. Louisiana senator Huey Long broke with the New Deal in 1934 and founded the Share Our Wealth Society, advocating a 100 percent tax on income over $1 million and inheritances over $5 million. The radio priest Father Charles Coughlin, with 30 million listeners, demanded bank nationalization through his National Union for Social Justice.", "what_zh": "民粹左翼批评新政做得不够。汤森医生提出老年循环养老金计划（60岁以上公民每月200美元），汤森俱乐部遍布全国。路易斯安那州参议员休伊·朗1934年与新政决裂，创立分享财富协会，主张对超100万美元收入和超500万美元遗产征100%的税。拥有三千万听众的考夫林神父通过全国社会正义联盟要求银行国有化。", "cause_en": "The belief that the New Deal favored corporations over ordinary citizens, amid Depression desperation.", "cause_zh": "认为新政偏袒企业而非普通百姓，加之大萧条的绝望。", "sig_en": "Roosevelt feared a third-party alliance of Townsend, Long, and Coughlin and moved left, adopting parts of their programs in the Second New Deal.", "sig_zh": "罗斯福担心三人结成第三党，被迫左转，在第二波新政中采纳了他们部分主张。", "exp_en": "Long, Townsend, and Coughlin threatened Roosevelt from the left and pushed him into the Second New Deal's welfare-state turn.", "exp_zh": "朗、汤森和考夫林从左翼威胁罗斯福，把他推向第二波新政的福利国家转向。", "page": 747}, {"id": "p7-041", "period": 7, "topic_en": "Wagner Act", "topic_zh": "瓦格纳法", "year": 1935, "year_text": "1935", "who": ["Robert F. Wagner"], "who_zh": ["罗伯特·F·瓦格纳"], "what_en": "Named for Senator Robert F. Wagner of New York, the Wagner Act (1935) upheld the right of industrial workers to join unions. It outlawed employer practices used to suppress unions, such as firing workers for organizing, and established the National Labor Relations Board (NLRB) to protect workers from coercion and guarantee collective bargaining.", "what_zh": "以纽约州参议员罗伯特·F·瓦格纳命名的1935年《瓦格纳法》保障产业工人加入工会的权利。它禁止雇主镇压工会的做法（如因组织工会开除工人），并设立全国劳工关系委员会（NLRB）保护工人免受胁迫、保障集体谈判。", "cause_en": "The 1934 strike wave and labor's demand for new protections after the Supreme Court voided the NIRA's Section 7(a).", "cause_zh": "1934年罢工浪潮，以及最高法院推翻国家工业复兴法第7条a款后劳工对新保护的需求。", "sig_en": "Union membership tripled to 23 percent of the nonagricultural workforce by decade's end, fueling the CIO and industrial unionism; the Court later upheld the act.", "sig_zh": "十年末工会会员增至三倍，占非农劳动力23%，推动产联和产业工会主义；法院后来维持该法。", "exp_en": "The Wagner Act was labor's Magna Carta: federal law finally guaranteed workers the right to organize and bargain collectively.", "exp_zh": "瓦格纳法是劳工的大宪章：联邦法律终于保障工人组织和集体谈判的权利。", "page": 747}, {"id": "p7-042", "period": 7, "topic_en": "Social Security Act", "topic_zh": "社会保障法", "year": 1935, "year_text": "1935", "who": ["Franklin Delano Roosevelt"], "who_zh": ["富兰克林·德拉诺·罗斯福"], "what_en": "The Social Security Act of 1935 had three main provisions: old-age pensions for workers; a joint federal-state system of compensation for unemployed workers; and payments to widowed mothers and the blind, deaf, and disabled. Roosevelt dropped national health insurance, fearing it would doom the bill, and domestic and agricultural workers, most of them African American, were excluded.", "what_zh": "1935年《社会保障法》有三大支柱：工人老年养老金、联邦与州合办的失业补偿、给寡母及盲聋残人士的补助。罗斯福担心全国医保会拖累整个法案而将其删除；家政和农业工人（多为非裔）被排除在外。", "cause_en": "Pressure from the Townsend and Long movements, the poverty of the elderly, and the example of European pension systems.", "cause_zh": "汤森和朗运动的压力、老年人的贫困，以及欧洲养老金制度的示范。", "sig_en": "A milestone in creating the American welfare state: never before had the federal government assumed such responsibility for citizens' well-being; it became one of the most popular programs in American history.", "sig_zh": "创建美国福利国家的里程碑：联邦政府从未承担过如此重大的民生责任；它成为美国历史上最受欢迎的项目之一。", "why_term": "welfare state", "why_term_q": "The Second New Deal created the American ______, in which government guarantees economic security.", "exp_en": "Social Security made the federal government the guarantor of old-age security, the heart of the New Deal welfare state.", "exp_zh": "社会保障使联邦政府成为老年保障的担保人，是新政福利国家的心脏。", "page": 747}, {"id": "p7-043", "period": 7, "topic_en": "Dust Bowl", "topic_zh": "沙尘暴灾区", "year": null, "year_text": "1930-1941", "who": ["John Steinbeck", "Dorothea Lange"], "who_zh": ["约翰·斯坦贝克", "多萝西娅·兰格"], "what_en": "Between 1930 and 1941 a severe drought afflicted the semiarid plains of Oklahoma, Texas, New Mexico, Colorado, Arkansas, and Kansas. Farmers had stripped the land of native vegetation and pushed wheat beyond the soil's natural limits, so winds raised huge clouds of dust that turned day into night. At least 350,000 Okies fled to California; John Steinbeck's The Grapes of Wrath (1939) and Dorothea Lange's photographs made them the public face of the Depression's human toll.", "what_zh": "1930至1941年严重干旱袭击俄克拉荷马、得克萨斯、新墨西哥、科罗拉多、阿肯色、堪萨斯的半干旱平原。农民剥去原生植被、把小麦种到土壤极限之外，大风卷起遮天蔽日的沙尘，白昼如夜。至少35万俄克佬逃往加州；斯坦贝克《愤怒的葡萄》（1939）和兰格的照片使他们成为大萧条人间代价的公众面孔。", "cause_en": "Drought combined with destructive farming practices on marginal land that destroyed the plains' delicate ecology.", "cause_zh": "干旱加上在边缘土地上破坏性的耕作方式，摧毁了平原脆弱的生态。", "sig_en": "The disaster prompted federal soil conservation: the Soil Conservation Service taught contour plowing and the Shelterbelts planted 220 million trees as a windbreak.", "sig_zh": "灾难促使联邦推行水土保持：水土保持局教授等高耕作，防风林带种植2.2亿棵树作防风屏障。", "exp_en": "The Dust Bowl was the Depression's ecological catastrophe, driving Okies west and Washington into soil conservation.", "exp_zh": "沙尘暴是大萧条的生态灾难，把俄克佬赶往西部，也把华盛顿推向水土保持。", "page": 759, "img": {"file": "img:f2_1109", "credit": "图源：Henretta《America's History》第8版 p.759"}}, {"id": "p7-044", "period": 7, "topic_en": "Court-packing plan", "topic_zh": "法院改组计划", "year": 1937, "year_text": "1937", "who": ["Franklin Delano Roosevelt"], "who_zh": ["富兰克林·德拉诺·罗斯福"], "what_en": "In 1937 Roosevelt surprised the nation by asking Congress to add a new Supreme Court justice for every member over seventy, which would have brought six new judges to the bench. With the Wagner Act, the TVA, and Social Security all slated to come before a Court that had struck down New Deal laws 5 to 4, the New Deal's future hung on a few elderly conservative justices. Opponents protested that he was trying to pack the Court, and after a bitter months-long debate Congress rejected the plan.", "what_zh": "1937年罗斯福出人意料地要求国会为每位年过七十的大法官增补一名新法官，当时可增补六人。瓦格纳法、TVA和社会保障法都将送交这个曾以5比4推翻新政法律的法院，新政前途系于几位年迈保守大法官之手。反对者抗议他要填塞法院，经过数月激烈辩论，国会否决了该计划。", "cause_en": "The Court's 5-4 invalidation of New Deal measures and the threat to pending Wagner, TVA, and Social Security cases.", "cause_zh": "法院以5比4推翻新政措施，以及待审的瓦格纳法、TVA和社会保障案受到的威胁。", "sig_en": "Roosevelt lost the battle but won the war: the Court upheld the Wagner and Social Security Acts, and timely resignations let him reshape the Court with liberals like Hugo Black, Felix Frankfurter, and William O. Douglas.", "sig_zh": "罗斯福输了战役赢了战争：法院维持了瓦格纳法和社会保障法，适时的辞职让他用布莱克、弗兰克福特、道格拉斯等自由派重塑了法院。", "exp_en": "The court-packing fight was Roosevelt's boldest overreach: Congress said no, but the Court got the message and stopped killing the New Deal.", "exp_zh": "法院改组之争是罗斯福最大胆的越权：国会说了不，但法院收到了信号，不再扼杀新政。", "page": 750}, {"id": "p7-045", "period": 7, "topic_en": "Indian Reorganization Act", "topic_zh": "印第安人重组法", "year": 1934, "year_text": "1934", "who": ["John Collier"], "who_zh": ["约翰·科利尔"], "what_en": "Commissioner of Indian Affairs John Collier helped write and push through Congress the Indian Reorganization Act of 1934, sometimes called the Indian New Deal. It reversed the Dawes Act of 1887 by promoting Indian self-government through formal constitutions and democratically elected tribal councils; 181 tribes accepted and 77 declined. Indians won greater religious freedom, and tribal governments regained status as semisovereign dependent nations.", "what_zh": "印第安事务局长约翰·科利尔推动国会通过1934年《印第安人重组法》，即印第安新政。它逆转1887年《道斯法案》，通过正式宪法和民选部落议会促进印第安自治；181个部落接受，77个拒绝。印第安人赢得更大的宗教自由，部落政府恢复半主权属国地位。", "cause_en": "Decades of forced assimilation, banned religions, and land confiscation had left tribes poor and powerless; in 1934 average Indian income was only $48 a year.", "cause_zh": "数十年的强制同化、宗教禁令和土地没收使部落贫穷无权；1934年印第安人年均收入仅48美元。", "sig_en": "It ended the worst federal practices like forced boarding schools and allotment sales, a mixed blessing that nonetheless began greater tribal autonomy.", "sig_zh": "它终结了强制寄宿学校、份地出售等最恶劣的联邦做法，虽褒贬不一，却开启了部落更大的自治。", "exp_en": "The Indian New Deal tried to undo allotment and assimilation, trading forced individualism for tribal self-government.", "exp_zh": "印第安新政试图废除份地制和同化政策，用部落自治取代强制的个人主义。", "page": 756, "img": {"file": "img:f2_1102", "credit": "图源：Henretta《America's History》第8版 p.756"}}, {"id": "p7-046", "period": 7, "topic_en": "Rise of fascism", "topic_zh": "法西斯主义的兴起", "year": null, "year_text": "1930s (Hitler becomes chancellor 1933)", "who": ["Benito Mussolini", "Adolf Hitler", "Hideki Tojo", "Francisco Franco"], "who_zh": ["贝尼托·墨索里尼", "阿道夫·希特勒", "东条英机", "弗朗西斯科·佛朗哥"], "what_en": "The Depression wrecked traditional politics, and fascism, an antidemocratic movement combining a centralized authoritarian state, intense nationalism, and disparagement of parliaments, unions, and individual rights, took power: Mussolini in Italy (1922), Hitler in Nazi Germany (chancellor 1933, then dictator pursuing lebensraum and Aryan supremacy), Franco in Spain, and after 1940 Tojo in Japan. Aggression followed: Japan occupied Manchuria (1931) and invaded China (1937); Italy invaded Ethiopia (1935); Hitler remilitarized the Rhineland (1936). The League of Nations stopped none of them.", "what_zh": "大萧条摧毁传统政治，法西斯主义这一反民主运动上台：中央集权的威权国家、极端民族主义，蔑视议会、工会和个人权利。墨索里尼统治意大利（1922），希特勒成为德国总理（1933）后独裁并追求生存空间和雅利安至上，佛朗哥统治西班牙，1940年后东条英机主政日本。侵略接踵而至：日本占领满洲（1931）、全面侵华（1937），意大利入侵埃塞俄比亚（1935），希特勒重占莱茵兰（1936）。国联无一能阻止。", "cause_en": "The unresolved settlement of World War I (Versailles resentments, thwarted imperial ambitions) plus the Depression's economic wreckage.", "cause_zh": "一战遗留的未决问题（凡尔赛怨恨、受挫的帝国野心）加上大萧条的经济浩劫。", "sig_en": "Fascist aggression set the stage for World War II; by 1937 Hitler had seized the military advantage in Europe.", "sig_zh": "法西斯侵略为二战铺路；到1937年希特勒已在欧洲取得军事优势。", "exp_en": "Fascism was the Depression's political poison: dictators who promised order and glory, and a League too weak to stop them.", "exp_zh": "法西斯主义是大萧条的政治毒药：承诺秩序与荣耀的独裁者，以及无力阻止他们的国联。", "page": 768}, {"id": "p7-047", "period": 7, "topic_en": "Neutrality Acts", "topic_zh": "中立法案", "year": 1935, "year_text": "1935-1937 (first act 1935)", "who": ["Gerald P. Nye", "Charles A. Lindbergh"], "who_zh": ["杰拉尔德·P·奈", "查尔斯·A·林德伯格"], "what_en": "After Senator Gerald P. Nye's 1934 investigation alleged that munitions makers, the merchants of death, had maneuvered Wilson into World War I, an isolationist Congress passed neutrality acts: the 1935 act embargoed arms sales to warring countries and warned Americans traveling on belligerent ships they did so at their own risk; the 1936 act banned loans to belligerents; the 1937 act imposed cash-and-carry for nonmilitary goods. Isolationists like Senator Robert Taft, aviator Charles Lindbergh, and the America First Committee forced Roosevelt to approach the brewing war cautiously.", "what_zh": "奈参议员1934年调查指控军火商即死亡商人把威尔逊推进一战后，孤立主义国会通过中立法案：1935年法案禁向交战国售武，警告乘坐交战国船只的美国人风险自负；1936年法案禁向交战国贷款；1937年法案对非军用物资实行现购自运。塔夫脱参议员、飞行员林德伯格和美国第一委员会等孤立主义者迫使罗斯福谨慎应对酝酿中的战争。", "cause_en": "Disillusionment with American participation in World War I and fear of being drawn into another European war.", "cause_zh": "对美国参加一战的幻灭，以及对被拖入另一场欧洲战争的恐惧。", "sig_en": "The acts kept the United States officially neutral but constrained FDR, who later chipped away at them with cash-and-carry for arms (1939) and the destroyers-for-bases deal (1940).", "sig_zh": "法案使美国在官方上保持中立，但束缚了罗斯福，他后来以军火现购自运（1939）和驱逐舰换基地（1940）逐步突破。", "why_term": "cash-and-carry", "why_term_q": "The 1937 Neutrality Act let belligerents buy nonmilitary goods only on a ______ basis.", "exp_en": "The Neutrality Acts tried to legislate America out of another world war; Roosevelt spent 1939-1941 dismantling them step by step.", "exp_zh": "中立法案试图用立法让美国远离另一场世界大战；罗斯福在1939至1941年一步步将其拆解。", "page": 769, "img": {"file": "img:f2_1160", "credit": "图源：Henretta《America's History》第8版 p.769"}}, {"id": "p7-048", "period": 7, "topic_en": "Munich Conference and appeasement", "topic_zh": "慕尼黑会议与绥靖政策", "year": 1938, "year_text": "September 1938", "who": ["Adolf Hitler", "Neville Chamberlain"], "who_zh": ["阿道夫·希特勒", "内维尔·张伯伦"], "what_en": "After Hitler annexed Austria and threatened Czechoslovakia, Britain and France met him at the Munich Conference in September 1938 and agreed to let Germany annex the Sudetenland in return for Hitler's pledge to seek no more territory. Chamberlain declared the agreement guaranteed peace for our time. Within six months Hitler overran the rest of Czechoslovakia. Then the Nazi-Soviet nonaggression pact (August 1939) freed Hitler from a two-front war; on September 1, 1939 he invaded Poland, and two days later Britain and France declared war: World War II had begun.", "what_zh": "希特勒吞并奥地利并威胁捷克斯洛伐克后，英法1938年9月在慕尼黑会议上同意德国吞并苏台德区，换取希特勒不再扩张的承诺。张伯伦宣称协议保障了我们时代的和平。半年内希特勒吞并捷克剩余地区。随后苏德互不侵犯条约（1939年8月）使希特勒免于两线作战；1939年9月1日他入侵波兰，两天后英法宣战：二战爆发。", "cause_en": "British and French reluctance to confront Hitler and the hope that concessions would satisfy his ambitions.", "cause_zh": "英法不愿对抗希特勒，希望让步能满足其野心。", "sig_en": "Appeasement proved disastrous and became the textbook warning against capitulating to aggressors.", "sig_zh": "绥靖被证明是灾难，成为向侵略者让步的教科书式警告。", "why_term": "appeasement", "why_term_q": "Britain and France's policy of capitulating to Hitler's demands at Munich is called ______.", "src": {"text": "peace for our time.", "attr": "Neville Chamberlain"}, "exp_en": "Munich taught the world that feeding a dictator's demands only whets his appetite; appeasement failed within months.", "exp_zh": "慕尼黑让世界懂得，满足独裁者的要求只会助长其胃口；绥靖数月内即告失败。", "page": 770, "img": {"file": "img:f2_1163", "credit": "图源：Henretta《America's History》第8版 p.770"}}, {"id": "p7-049", "period": 7, "topic_en": "Lend-Lease Act", "topic_zh": "租借法案", "year": 1941, "year_text": "March 1941", "who": ["Franklin Delano Roosevelt", "Winston Churchill"], "who_zh": ["富兰克林·德拉诺·罗斯福", "温斯顿·丘吉尔"], "what_en": "With Britain no longer able to pay cash for arms, Roosevelt persuaded Congress in March 1941 to pass the Lend-Lease Act, authorizing the president to lease, lend, or otherwise dispose of arms and equipment to Britain or any country whose defense was vital to U.S. security. When Hitler invaded the Soviet Union in June 1941, the United States extended lend-lease to the Soviets. Its implementation marked the unofficial entrance of the United States into the European war.", "what_zh": "英国已无力现金购买军火，罗斯福说服国会1941年3月通过《租借法案》，授权总统向英国或任何对美国安全至关重要的国家租借、借出或以其他方式提供武器装备。1941年6月希特勒入侵苏联后，美国把租借扩展到苏联。该法的实施标志美国非正式进入欧洲战争。", "cause_en": "Britain's survival was seen as key to American security; FDR's strategy of making America the great arsenal of democracy.", "cause_zh": "英国的存亡被视为美国安全的关键；罗斯福把美国打造成民主兵工厂的战略。", "sig_en": "It ended the pretense of strict neutrality and tied American industrial production to Allied victory.", "sig_zh": "它终结了严格中立的伪装，把美国工业生产与盟国胜利绑在一起。", "src": {"text": "We must be the great arsenal of democracy.", "attr": "Franklin D. Roosevelt"}, "exp_en": "Lend-Lease turned American factories into the Allies' supply line, ending neutrality in everything but name.", "exp_zh": "租借法案把美国工厂变成盟国的补给线，终结了名义之外的中立。", "page": 771}, {"id": "p7-050", "period": 7, "topic_en": "Four Freedoms and Atlantic Charter", "topic_zh": "四大自由与大西洋宪章", "year": 1941, "year_text": "Four Freedoms January 1941; Atlantic Charter August 1941", "who": ["Franklin Delano Roosevelt", "Winston Churchill"], "who_zh": ["富兰克林·德拉诺·罗斯福", "温斯顿·丘吉尔"], "what_en": "In January 1941 Roosevelt delivered his Four Freedoms speech, defining four essential human freedoms: freedom of speech, freedom of religion, freedom from want, and freedom from fear, casting the war as a noble defense of democratic societies and linking it to the New Deal. In August 1941 he met British prime minister Winston Churchill and issued the Atlantic Charter, calling for economic cooperation, national self-determination, and postwar stability so that all men in all the lands may live out their lives in freedom from fear and want.", "what_zh": "1941年1月罗斯福发表四大自由演说，定义四项基本人类自由：言论自由、宗教自由、免于匮乏的自由、免于恐惧的自由，把战争描绘为民主社会的高尚保卫战，并与新政相连。1941年8月他会见英国首相丘吉尔，发表大西洋宪章，主张经济合作、民族自决和战后稳定，使各国人民得以免于恐惧和匮乏地生活。", "cause_en": "The need to define the war's purpose for Americans and rally support for aiding Britain.", "cause_zh": "需要为美国人阐明战争目的，争取对援英的支持。", "sig_en": "The two statements provided the ideological foundation of the Western cause and of a future American-led alliance, though the self-determination promise later clashed with European empires.", "sig_zh": "两份文件为西方事业和未来美国主导的同盟奠定思想基础，尽管自决承诺后来与欧洲帝国发生冲突。", "src": {"text": "that all men in all the lands may live out their lives in freedom from fear and want.", "attr": "Atlantic Charter"}, "exp_en": "The Four Freedoms and Atlantic Charter gave the coming war its democratic creed, from Wilson's ideals to Roosevelt's welfare-state vision.", "exp_zh": "四大自由和大西洋宪章赋予即将到来的战争民主信条，从威尔逊的理想延续到罗斯福的福利国家愿景。", "page": 772, "img": {"file": "img:f2_1167", "credit": "图源：Henretta《America's History》第8版 p.772"}}, {"id": "p7-051", "period": 7, "topic_en": "Attack on Pearl Harbor", "topic_zh": "珍珠港事件", "year": 1941, "year_text": "December 7, 1941", "who": ["Hideki Tojo", "Franklin Delano Roosevelt", "Jeannette Rankin"], "who_zh": ["东条英机", "富兰克林·德拉诺·罗斯福", "珍妮特·兰金"], "what_en": "After Japan's full-scale invasion of Indochina in July 1941, Roosevelt froze Japanese assets and stopped all trade, including oil shipments that were almost 80 percent of Japanese consumption. General Tojo became prime minister in October 1941 and accelerated war preparations. Early on Sunday morning, December 7, 1941, Japanese bombers attacked Pearl Harbor in Hawaii, killing more than 2,400 Americans and destroying or heavily damaging eight battleships and almost two hundred airplanes. Calling it a date which will live in infamy, Roosevelt asked Congress for war; the Senate voted unanimously and the House 388 to 1, with Jeannette Rankin the lone dissenter. Three days later Germany and Italy declared war on the United States.", "what_zh": "1941年7月日本全面入侵印度支那后，罗斯福冻结日本资产并停止一切贸易，包括占日本消费近80%的石油。东条英机10月出任首相，加速战争准备。1941年12月7日周日清晨，日本轰炸机袭击夏威夷珍珠港，2400多名美国人丧生，八艘战列舰被击沉或重创，近二百架飞机被毁。罗斯福称这是国耻日，要求国会宣战；参议院一致通过，众议院388比1，仅兰金反对。三天后德意对美宣战。", "cause_en": "Japan's drive for a Greater East Asia Co-Prosperity Sphere collided with U.S. sanctions imposed over the invasion of China and Indochina.", "cause_zh": "日本建立大东亚共荣圈的扩张与美国因侵华和入侵印度支那而实施的制裁相撞。", "sig_en": "The attack united Americans and brought the United States fully into World War II in both Europe and Asia.", "sig_zh": "袭击团结了美国人，使美国全面卷入欧亚两大战场的二战。", "src": {"text": "a date which will live in infamy.", "attr": "Franklin D. Roosevelt"}, "exp_en": "Pearl Harbor ended isolationism in a single morning: the Pacific war Japan started forced America into a global war.", "exp_zh": "珍珠港在一个早晨终结了孤立主义：日本发动的太平洋战争把美国拖入全球战争。", "page": 773}, {"id": "p7-052", "period": 7, "topic_en": "Code talkers", "topic_zh": "密码通讯兵", "year": null, "year_text": "World War II (used at Iwo Jima, 1945)", "who": [], "who_zh": [], "what_en": "In the Pacific theater, native Navajo speakers communicated orders to fleet commanders in a code based on the Navajo language, which fewer than fifty non-Navajos in the world understood, so Japanese intelligence could not decipher it. At the battle of Iwo Jima, Navajo code talkers working around the clock sent and received more than eight hundred messages without error. In the European theater, Comanche, Choctaw, and Cherokee speakers thwarted the Nazis. No Axis nation ever broke these Native American codes.", "what_zh": "在太平洋战场，纳瓦霍语者用基于纳瓦霍语的密码向舰队指挥官传达命令，全球懂该语言的非纳瓦霍人不足五十，日军情报无法破译。在硫磺岛战役中，纳瓦霍密码通讯兵昼夜不停，收发八百多条信息无一差错。在欧洲战场，科曼奇、乔克托、切罗基语者挫败纳粹。轴心国从未破译这些印第安密码。", "cause_en": "The need for secure battlefield communications; Native Americans served in integrated units, unlike segregated Black troops.", "cause_zh": "战场安全通信的需求；印第安人在混合部队服役，不同于被隔离的黑人部队。", "sig_en": "Their unbreakable codes were instrumental to Allied battlefield communication in both theaters.", "sig_zh": "他们无法破译的密码对两大战场盟军通信至关重要。", "exp_en": "The code talkers turned Native languages into America's most secure wartime weapon, never broken by the Axis.", "exp_zh": "密码通讯兵把印第安语言变成美国最安全的战时武器，轴心国从未破译。", "page": 776}, {"id": "p7-053", "period": 7, "topic_en": "Executive Order 8802", "topic_zh": "8802号行政令", "year": 1941, "year_text": "June 1941", "who": ["A. Philip Randolph", "Franklin Delano Roosevelt", "Mary McLeod Bethune"], "who_zh": ["A·菲利普·伦道夫", "富兰克林·德拉诺·罗斯福", "玛丽·麦克劳德·白求恩"], "what_en": "In 1940 only 240 of the nation's 100,000 aircraft workers were Black. When Washington ignored demands for defense jobs, A. Philip Randolph, head of the Brotherhood of Sleeping Car Porters, announced a 1941 march on Washington. Roosevelt made a deal: in June 1941 he issued Executive Order 8802, prohibiting discrimination in the employment of workers in defense industries or government because of race, creed, color, or national origin, and establishing the Fair Employment Practices Commission (FEPC). Randolph canceled the march.", "what_zh": "1940年全国十万飞机制造工人中仅240名黑人。华盛顿无视就业诉求后，卧铺车厢搬运工兄弟会领袖伦道夫宣布1941年向华盛顿进军。罗斯福达成交易：1941年6月发布8802号行政令，禁止国防工业和政府雇佣中因种族、信仰、肤色或国籍的歧视，并设立公平就业实施委员会。伦道夫取消进军。", "cause_en": "Black labor activism and the Double V campaign (victory over Nazism abroad and racism at home); FDR wanted to avoid protest disrupting war preparations.", "cause_zh": "黑人劳工行动主义和双V运动（国外战胜纳粹、国内战胜种族主义）；罗斯福想避免抗议干扰备战。", "sig_en": "It was the first federal commitment to Black employment rights, unprecedented but limited: it did not touch military segregation and the FEPC could not enforce compliance. Still, it laid groundwork for the 1960s civil rights revolution.", "sig_zh": "它是联邦对黑人就业权利的首次承诺，前所未有但有限：未触及军队隔离，委员会也无执法权。但它为1960年代民权革命奠定基础。", "src": {"text": "discrimination in the employment of workers in defense industries or government because of race, creed, color, or national origin", "attr": "Executive Order 8802"}, "exp_en": "Randolph's threatened march forced the first federal fair-employment order, the wartime seed of the civil rights movement.", "exp_zh": "伦道夫威胁进军迫使联邦发布首个公平就业令，成为民权运动的战时种子。", "page": 780, "img": {"file": "img:f2_1211", "credit": "图源：Henretta《America's History》第8版 p.780"}}, {"id": "p7-054", "period": 7, "topic_en": "GI Bill of Rights", "topic_zh": "退伍军人权利法案", "year": 1944, "year_text": "1944", "who": ["Franklin Delano Roosevelt"], "who_zh": ["富兰克林·德拉诺·罗斯福"], "what_en": "The Servicemen's Readjustment Act (1944), popularly known as the GI Bill of Rights, provided education, job training, medical care, pensions, and mortgage loans for men and women who had served in the armed forces. Incredibly, in 1950 World War II veterans made up one-third of all American men over the age of nineteen.", "what_zh": "1944年《退伍军人调整法案》即退伍军人权利法案，为服役男女提供教育、职业培训、医疗、养老金和住房抵押贷款。1950年，二战老兵竟占全美19岁以上男性的三分之一。", "cause_en": "FDR's 1944 call for a second Bill of Rights guaranteeing economic security, and the need to reintegrate fifteen million returning servicemembers.", "cause_zh": "罗斯福1944年呼吁保障经济安全的第二权利法案，以及安置1500万复员军人的需要。", "sig_en": "It transformed American higher education and homeownership and made veterans central to postwar national life.", "sig_zh": "它改变了美国高等教育和住房拥有率，使老兵成为战后国家生活的中心。", "exp_en": "The GI Bill turned wartime service into college degrees and suburban homes, building the postwar middle class.", "exp_zh": "退伍军人权利法案把战时服役变成大学文凭和郊区住宅，塑造了战后中产阶级。", "page": 781}, {"id": "p7-055", "period": 7, "topic_en": "Zoot-suit riots", "topic_zh": "佐特装骚乱", "year": 1943, "year_text": "June 1943", "who": [], "who_zh": [], "what_en": "In Los Angeles, Mexican American pachuco youth wore zoot suits: broad-brimmed felt hats, thigh-length jackets with wide lapels and padded shoulders, pegged trousers. To many adults the style symbolized juvenile delinquency and rejection of middle-class values. In June 1943 rumors that a pachuco gang had beaten an Anglo sailor set off a four-day riot in which hundreds of Anglo servicemen roamed Mexican American neighborhoods attacking zoot-suiters and slashing their pegged pants. Police arrested only Mexican American youth, and the City Council outlawed wearing the zoot suit.", "what_zh": "在洛杉矶，墨西哥裔帕丘科青年穿佐特装：宽檐毡帽、宽翻领垫肩的及膝长夹克、窄腿裤。在许多成年人眼中，这种风格象征少年犯罪和对中产价值观的拒绝。1943年6月，帕丘科帮殴打白人士兵的谣言引发四天骚乱，数百名白人士兵闯入墨西哥裔社区袭击佐特装青年，割破他们的窄腿裤。警方只逮捕墨西哥裔青年，市议会立法禁止穿佐特装。", "cause_en": "Wartime migration mixed races in booming cities; competition for jobs and housing; generational and cultural friction.", "cause_zh": "战时迁移使各族裔在繁荣城市交汇；就业住房竞争；代际与文化摩擦。", "sig_en": "The riots, alongside 1943 race riots in Detroit (thirty-four dead) and conflicts in over a hundred cities, exposed cracks in wartime unity on the home front.", "sig_zh": "该骚乱与1943年底特律种族骚乱（34人死亡）及上百城市的冲突一起，暴露了后方战时团结的裂痕。", "why_term": "zoot suit", "why_term_q": "The flamboyant outfit worn by Mexican American pachuco youth in 1940s Los Angeles was the ______.", "exp_en": "The zoot-suit riots showed that wartime Los Angeles was a battleground over race, youth culture, and who counted as American.", "exp_zh": "佐特装骚乱表明，战时的洛杉矶是种族、青年文化和谁算美国人的战场。", "page": 783}, {"id": "p7-056", "period": 7, "topic_en": "Executive Order 9066 and Japanese internment", "topic_zh": "9066号行政令与日裔拘禁", "year": 1942, "year_text": "early 1942", "who": ["Franklin Delano Roosevelt", "Gordon Hirabayashi"], "who_zh": ["富兰克林·德拉诺·罗斯福", "戈登·平林"], "what_en": "Early in 1942 Roosevelt issued Executive Order 9066, authorizing the War Department to force Japanese Americans from West Coast homes into relocation camps in desolate interior areas. About 112,000 people were imprisoned, more than two-thirds of them Nisei, native-born American citizens, though no disloyal activity was found. Gordon Hirabayashi resisted and lost in the Supreme Court: Hirabayashi v. United States (1943) and Korematsu v. United States (1944) allowed removal on military necessity. Congress apologized in 1988 and paid $20,000 to each surviving internee.", "what_zh": "1942年初罗斯福发布9066号行政令，授权陆军部把西岸日裔美国人强制迁入内陆荒凉地区的安置营。约11.2万人被监禁，三分之二以上是二世即本土出生的美国公民，尽管未发现任何不忠行为。平林戈登反抗并在最高法院败诉：平林案（1943）和是松案（1944）以军事必要为由允许驱逐。国会1988年道歉并向每位在世被拘禁者赔偿2万美元。", "cause_en": "Pearl Harbor panic plus California's long history of anti-Asian racism; unlike German and Italian Americans, Japanese Americans were singled out.", "cause_zh": "珍珠港恐慌加上加州长期的反亚裔种族主义；与德裔意裔美国人不同，日裔被单独挑出来。", "sig_en": "The internment was a glaring exception to wartime tolerance and underscored the fragility of civil liberties in wartime.", "sig_zh": "拘禁是战时宽容政策中刺眼的例外，凸显战时公民自由的脆弱。", "src": {"text": "I wanted to uphold the principles of the Constitution, and the curfew and evacuation orders which singled out a group on the basis of ethnicity violated them.", "attr": "Gordon Hirabayashi"}, "exp_en": "Executive Order 9066 imprisoned 112,000 Japanese Americans without evidence of disloyalty, the war's starkest violation of civil liberties.", "exp_zh": "9066号行政令在没有不忠证据的情况下监禁11.2万日裔美国人，是战争中最严重的公民自由侵犯。", "page": 787, "img": {"file": "img:f2_1234", "credit": "图源：Henretta《America's History》第8版 p.787"}}, {"id": "p7-057", "period": 7, "topic_en": "D-Day", "topic_zh": "诺曼底登陆", "year": 1944, "year_text": "June 6, 1944", "who": ["Dwight D. Eisenhower"], "who_zh": ["德怀特·D·艾森豪威尔"], "what_en": "The long-promised invasion of France came on D-Day, June 6, 1944: the largest armada ever assembled crossed the English Channel under General Eisenhower. American, British, and Canadian soldiers stormed the Normandy beaches, suffering terrible casualties (more than 10,000 killed or wounded that day among 156,000 troops) but securing a beachhead. Within a month 1 million Allied troops were ashore; in August Paris was liberated, and by September the Germans had been driven from most of France and Belgium.", "what_zh": "期盼已久的法国登陆在1944年6月6日到来：史上最大舰队在艾森豪威尔指挥下横渡英吉利海峡。美英加士兵强攻诺曼底海滩，伤亡惨重（15.6万人中当日伤亡逾万）但站稳滩头。一个月内百万盟军上岸；8月巴黎解放；9月德军被赶出法比大部。", "cause_en": "Stalin's long-demanded second front, finally agreed at Tehran (November 1943) after the Soviet Union bore the brunt of the fighting.", "cause_zh": "斯大林长期要求的第二战场，在苏联承担作战重担后终于在德黑兰会议（1943年11月）达成协议。", "sig_en": "D-Day opened the western front that, combined with the Soviet advance from the east, doomed Nazi Germany, which surrendered on May 7, 1945.", "sig_zh": "诺曼底登陆开辟西线，与苏联东线夹击注定纳粹德国灭亡，德国1945年5月7日投降。", "src": {"text": "The eyes of the world are upon you.", "attr": "Dwight D. Eisenhower"}, "exp_en": "D-Day was the Allies' great gamble in the west: one day of landings that began the eleven-month drive to Berlin.", "exp_zh": "诺曼底登陆是盟军在西线的大赌博：一天的登陆开启了十一个月直捣柏林的征程。", "page": 790, "img": {"file": "img:f2_1245", "credit": "图源：Henretta《America's History》第8版 p.790"}}, {"id": "p7-058", "period": 7, "topic_en": "Holocaust", "topic_zh": "大屠杀", "year": null, "year_text": "early 1940s (camps liberated spring 1945)", "who": ["Adolf Hitler"], "who_zh": ["阿道夫·希特勒"], "what_en": "When Allied troops advanced into Poland and Germany in spring 1945, they found Hitler's final solution: extermination camps such as Buchenwald, Dachau, and Auschwitz, in which 6 million Jews had been put to death along with another 6 million Poles, Slavs, Gypsies, homosexuals, and other undesirables. The United States had refused to relax immigration laws: in 1939 FDR turned away the SS St. Louis with nearly a thousand Jewish refugees, and the State Department admitted only 21,000 Jewish refugees during the war. FDR's 1944 War Refugee Board helped move 200,000 European Jews to safe havens.", "what_zh": "1945年春盟军推进到波兰和德国时，发现了希特勒的最终解决：布痕瓦尔德、达豪、奥斯威辛等灭绝营，600万犹太人被杀害，另有600万波兰人、斯拉夫人、吉普赛人、同性恋等不受欢迎者遇难。美国拒绝放宽移民法：1939年罗斯福拒绝载有近千名犹太难民的圣路易斯号靠岸，国务院在战争期间仅接纳2.1万犹太难民。罗斯福1944年设立的战争难民委员会帮助20万欧洲犹太人转移到安全地带。", "cause_en": "Nazi ideology of Aryan supremacy and the campaign of extermination; U.S. inaction driven by anti-Semitism, 1920s immigration restrictions, and isolationism.", "cause_zh": "纳粹雅利安至上意识形态和灭绝运动；美国的不作为源于反犹主义、1920年代移民限制和孤立主义。", "sig_en": "Published photographs of the camps horrified the world, and the Holocaust became the war's central moral reckoning.", "sig_zh": "集中营照片公之于众震惊世界，大屠杀成为这场战争的核心道德清算。", "exp_en": "The Holocaust revealed the endpoint of Nazi racial ideology, and America's closed doors remain part of its history.", "exp_zh": "大屠杀揭示了纳粹种族意识形态的终点，而美国紧闭的大门也是这段历史的一部分。", "page": 792}, {"id": "p7-059", "period": 7, "topic_en": "Manhattan Project and the atomic bomb", "topic_zh": "曼哈顿计划与原子弹", "year": 1945, "year_text": "bombs dropped August 6 and 9, 1945", "who": ["J. Robert Oppenheimer", "Leslie Groves", "Harry S. Truman", "Enrico Fermi", "Albert Einstein"], "who_zh": ["J·罗伯特·奥本海默", "莱斯利·格罗夫斯", "哈里·S·杜鲁门", "恩里科·费米", "阿尔伯特·爱因斯坦"], "what_en": "The top-secret Manhattan Project cost $2 billion, employed 120,000 people, and built thirty-seven installations in nineteen states, hidden even from Vice President Truman. Enrico Fermi and Leo Szilard produced the first controlled atomic chain reaction in December 1942, and with Albert Einstein's help persuaded Roosevelt to build the weapon. Directed by General Leslie Groves and scientist J. Robert Oppenheimer, physicists assembled the first bomb at Los Alamos and tested it on July 16, 1945. Truman ordered bombs dropped on Hiroshima (August 6) and Nagasaki (August 9), killing 100,000 and 60,000; Japan surrendered unconditionally on August 10.", "what_zh": "绝密的曼哈顿计划耗资20亿美元，雇佣12万人，在19个州建37处设施，连副总统杜鲁门都被蒙在鼓里。费米和西拉德1942年12月实现首次可控原子链式反应，并在爱因斯坦帮助下说服罗斯福研制原子武器。在格罗夫斯将军和科学家奥本海默领导下，物理学家在洛斯阿拉莫斯组装出第一颗原子弹，1945年7月16日试爆成功。杜鲁门下令在广岛（8月6日）和长崎（8月9日）投弹，分别造成10万和6万人死亡；日本8月10日无条件投降。", "cause_en": "Fear that German scientists were building such a weapon; the belief that only national ruin would force Japan's surrender; the Potsdam demand for unconditional surrender; invasion casualty estimates of half a million to a million Allied troops.", "cause_zh": "担心德国科学家也在研制；认为只有国家毁灭才能迫使日本投降；波茨坦要求无条件投降；登陆日本预计盟军伤亡五十万至一百万。", "sig_en": "The bombs ended World War II and opened the atomic age; Truman's rationale remains the subject of scholarly and popular debate.", "sig_zh": "原子弹终结二战并开启原子时代；杜鲁门的决策理由至今仍是学界和公众争论的话题。", "src": {"text": "I am become Death, the Destroyer of Worlds.", "attr": "J. Robert Oppenheimer, recalling the Bhagavad Gita"}, "exp_en": "The Manhattan Project turned physics into history's most terrible weapon and forced the surrender that ended the war.", "exp_zh": "曼哈顿计划把物理学变成历史上最可怕的武器，迫使日本投降，终结战争。", "page": 793, "img": {"file": "img:f2_1258", "credit": "图源：Henretta《America's History》第8版 p.793"}}, {"id": "p7-060", "period": 7, "topic_en": "Yalta Conference and the United Nations", "topic_zh": "雅尔塔会议与联合国", "year": 1945, "year_text": "Yalta Conference February 1945; United Nations founded 1945", "who": ["Franklin Delano Roosevelt", "Winston Churchill", "Joseph Stalin"], "who_zh": ["富兰克林·德拉诺·罗斯福", "温斯顿·丘吉尔", "约瑟夫·斯大林"], "what_en": "With victory in Europe at hand, Roosevelt journeyed in February 1945 to Yalta, on the Black Sea, and met for the final time with Churchill and Stalin. The Big Three discussed the treatment of Germany, the status of Poland, the creation of the United Nations, and Soviet entry into the war against Japan. The Yalta agreements mirrored a new balance of power and set the stage for the Cold War. The United Nations was founded in 1945 as the successor to the failed League of Nations.", "what_zh": "欧洲胜利在望之际，罗斯福1945年2月远赴黑海之滨的雅尔塔，与丘吉尔、斯大林最后一次会晤。三巨头讨论德国处置、波兰地位、联合国创建和苏联对日参战。雅尔塔协议反映新的力量平衡，为冷战拉开序幕。联合国1945年成立，接替失败的国联。", "cause_en": "The need to settle the postwar order and secure Soviet help against Japan as Germany's defeat approached.", "cause_zh": "德国败亡在即，需要安排战后秩序并争取苏联对日作战。", "sig_en": "Yalta shaped the postwar world and the coming Cold War; the UN embodied a second attempt at Wilson's collective-security vision.", "sig_zh": "雅尔塔塑造了战后世界和即将到来的冷战；联合国体现了对威尔逊集体安全愿景的第二次尝试。", "exp_en": "Yalta divided the spoils of victory and founded the United Nations, drawing the map of the Cold War world.", "exp_zh": "雅尔塔瓜分胜利果实并创建联合国，绘制了冷战世界的地图。", "page": 795, "img": {"file": "img:f2_1267", "credit": "图源：Henretta《America's History》第8版 p.795"}}];